22	namespace optimize {
23	class FusionCaseGenerator {
24	 public:
25	  FusionCaseGenerator() = default;
26	  virtual ~FusionCaseGenerator() = default;
27	  FusionCaseGenerator(const FusionCaseGenerator &) = delete;
28	  FusionCaseGenerator &operator=(const FusionCaseGenerator &) = delete;
29	  virtual Status Generate(ascir::HintGraph &graph, std::vector<ascir::ImplGraph> &graphs,
30	                          std::vector<std::string> &score_functions) = 0;
31	  virtual Status GeneratorTask(ascir::HintGraph &optimize_graph, std::vector<ScheduleTask> &tasks,
32	                               const OptimizerOptions &options) {
33	    (void)options;
34	    bool need_update_axis = false;
35	    GE_ASSERT_SUCCESS(ScheduleGroupGraphPartitioner::NeedRefreshAxisSize(optimize_graph, need_update_axis));
36	    std::vector<ascir::ImplGraph> optimize_graphs;
37	    std::vector<std::string> score_funcs;
38	    GE_CHK_STATUS_RET(Generate(optimize_graph, optimize_graphs, score_funcs), "GenerateScheduleCases failed");
39	    score_funcs.resize(optimize_graphs.size());
40	    for (size_t i = 0U; i < optimize_graphs.size(); ++i) {
41	      const auto &graph = optimize_graphs[i];
42	      ScheduleTask task{graph, {}, score_funcs[i]};
43	      task.has_load_store_conversion = HasLoadStoreConversion();
44	      GE_CHK_STATUS_RET(ScheduleGroupGraphPartitioner::PartitionByConnectivity(graph, task.grouped_graphs),
45	                        "Failed to partition graph");
46	      if (need_update_axis && task.grouped_graphs.size() > 1) {
47	        GE_ASSERT_SUCCESS(UpdateAxisSizes(task.grouped_graphs));
48	      }
49	      uint32_t max_group_num = 32U;
50	      if (options.graph_type == GraphType::kFusedAscBackend) {
51	        const auto backend_spec = BackendSpec::GetInstance();
52	        GE_ASSERT_NOTNULL(backend_spec);
53	        max_group_num = backend_spec->max_group_num_per_compile_unit;
54	      }
55	      if (options.graph_type == GraphType::kFusedAscBackend) {
56	        GE_CHK_STATUS_RET(ScheduleGroupGraphPartitioner::ReduceGraphCount(task.grouped_graphs, max_group_num),
57	                          "Failed to reduce graph count");
58	      }
59	      tasks.emplace_back(std::move(task));
60	    }
61	    return af::GRAPH_SUCCESS;
62	  }
63	
64	  static Status GroupPartitionAndGenTasks(const ascir::ImplGraph &impl_graph, std::vector<ScheduleTask> &tasks) {
65	    ::ascir::utils::DumpGraph(impl_graph, "BeforeGroupPartition");
66	    ScheduleTask new_schedule_task{impl_graph, {}, ""};
67	    GE_CHK_STATUS_RET(
68	        ScheduleGroupGraphPartitioner::PartitionByConnectivity(impl_graph, new_schedule_task.grouped_graphs),
69	        "Failed to partition graph [%s].", impl_graph.GetName().c_str());
70	    tasks.emplace_back(std::move(new_schedule_task));
71	    return af::SUCCESS;
72	  }
73	
74	  virtual bool HasLoadStoreConversion() const {
75	    return false;
76	  }
77	
78	 private:
79	  static Status UpdateAxisSizes(std::vector<::ascir::ImplGraph> &grouped_graphs) {
80	    for (const auto &subgraph : grouped_graphs) {
81	      if (ScheduleUtils::FindFirstNodeOfType<af::ascir_op::Concat>(subgraph) == nullptr) {
82	        GE_ASSERT_SUCCESS(ScheduleGroupGraphPartitioner::RefreshAxisSize(subgraph));
83	      }
84	    }
85	    return af::SUCCESS;
86	  }
87	};
88	}  // namespace optimize
89	#endif  // ASCGEN_DEV_SRC_OPTIMIZE_TASK_GENERATOR_SCHEDULE_CASE_GENERATOR_H_
