23	namespace optimize {
24	namespace {
25	constexpr int32_t kTransposeNoNeedUBConvertSize = 512;  // 以512Byte作为是否需要消除Transpose的阈值
26	constexpr char kTransposePrefix[] = "transpose_";
27	}  // namespace
28	
29	std::vector<af::AscNodePtr> TransposeFusionCaseGenerator::FindTransposeNodes(const ascir::HintGraph &owner_graph) {
30	  std::vector<af::AscNodePtr> transpose_nodes;
31	  for (const auto &node : owner_graph.GetAllNodes()) {
32	    if (af::ops::IsOps<af::ascir_op::Transpose>(node)) {
33	      transpose_nodes.emplace_back(node);
34	    }
35	  }
36	  return transpose_nodes;
37	}
38	
39	Status TransposeFusionCaseGenerator::TransposeNodeInputsAndOutputsCheck(const af::AscNodePtr &transpose_node) const {
40	  const auto &transpose_in_data_nodes = transpose_node->GetInDataNodes();
41	  GE_ASSERT_TRUE(transpose_in_data_nodes.size() == 1UL, "%zu nodes links to transpose node:%s",
42	                 transpose_in_data_nodes.size(), transpose_node->GetNamePtr());
43	  return af::SUCCESS;
44	}
45	
46	void TransposeFusionCaseGenerator::UpdateAxisByPath(::ascir::ImplGraph &owner_graph, const af::NodePtr &input_node,
47	                                                    std::set<af::Node *> &visited_nodes,
48	                                                    const std::vector<int64_t> &reordered_axis,
49	                                                    const std::vector<int64_t> &reordered_sched_axis) const {
50	  std::queue<af::NodePtr> path_nodes;
51	  path_nodes.emplace(input_node);
52	  while (!path_nodes.empty()) {
53	    auto top = path_nodes.front();
54	    path_nodes.pop();
55	    visited_nodes.emplace(top.get());
56	    ::ascir::NodeView input_view = std::dynamic_pointer_cast<af::AscNode>(top);
57	    if (!ScheduleUtils::IsBuffer(input_view)) {
58	      owner_graph.ApplyTensorAxisReorder(input_view, reordered_axis);
59	      owner_graph.ApplySchedAxisReorder(input_view, reordered_sched_axis);
60	      if (af::ops::IsOps<af::ascir_op::Load>(input_view)) {
61	        const std::string old_name = input_view->GetName();
62	        if (old_name.rfind(kTransposePrefix, 0U) != 0U) {
63	          input_view->GetOpDesc()->SetName(kTransposePrefix + old_name);
64	        }
65	      }
66	    }
67	    // 向上遍历。 暂时不考虑transpose之上的节点有额外向下的分支，如果有额外分支，则不能将transpose消除。
68	    for (size_t idx = 0UL; idx < top->GetInDataNodesSize(); ++idx) {
69	      if (visited_nodes.count(top->GetInDataNodes().at(idx).get()) == 0UL) {
70	        path_nodes.push(top->GetInDataNodes().at(idx));
71	      }
72	    }
73	  }
74	}
75	
76	void TransposeFusionCaseGenerator::UpdateAxis(ascir::HintGraph &graph, const af::AscNodePtr &transpose_node) const {
77	  std::vector<std::pair<int64_t, int64_t>> transpose_info;
78	  const auto &reordered_axis = transpose_node->outputs[0].attr.axis;
79	  const auto &reordered_sched_axis = transpose_node->attr.sched.axis;
80	  std::set<af::Node *> unused_visited_nodes;
81	  UpdateAxisByPath(graph, transpose_node, unused_visited_nodes, reordered_axis, reordered_sched_axis);
82	}
83	
84	Status TransposeFusionCaseGenerator::TransposeConvertProcess(ascir::HintGraph &graph,
85	                                                             const af::AscNodePtr &transpose_node) const {
86	  GE_CHK_STATUS_RET(TransposeNodeInputsAndOutputsCheck(transpose_node), "TransposeNode Check failed");
87	  UpdateAxis(graph, transpose_node);
88	
89	  auto owner_compute_graph = transpose_node->GetOwnerComputeGraph();
90	  GE_CHK_STATUS_RET(owner_compute_graph->RemoveNode(transpose_node), "Failed to remote node: %s",
91	                    transpose_node->GetNamePtr());
92	
93	  GE_ASSERT_GRAPH_SUCCESS(ScheduleUtils::TopologicalSorting(graph));
94	  ascir::utils::DumpGraph(graph, "AfterConvertTranspose");
95	  return af::SUCCESS;
96	}
97	
98	Status TransposeFusionCaseGenerator::Generate(ascir::HintGraph &graph, std::vector<ascir::ImplGraph> &graphs,
99	                                              std::vector<std::string> &score_functions) {
100	  /*
101	  单个Transpose场景：
102	    场景1： 尾轴转置， 需要UB重排，Transpose节点保留；
103	    场景2：非尾轴转置，尾轴大于等于512Byte，不需要UB重排，Transpose删除，刷新load/store表示；
104	    场景3：非尾轴转置，尾轴小于等于512Byte，需要UB重排，Transpose节点保留；
105	    同时提供两套模板，后续根据打分机制来选取
106	  多个Transpose场景：
107	    不生成保留模板，直接将所有Transpose行为推到load上
108	  */
109	
110	  const auto transpose_nodes = FindTransposeNodes(graph);
111	  if (transpose_nodes.empty()) {
112	    GELOGI("No transpose node found, skip");
113	    return af::SUCCESS;
114	  }
115	
116	  GraphPropertiesCache cache(graph);
117	  if (cache.HasReduce()) {
118	    // 存在不支持与Transpose融合的计算节点，直接在原图上消除所有Transpose
119	    auto remaining = FindTransposeNodes(graph);
120	    while (!remaining.empty()) {
121	      GE_CHK_STATUS_RET(TransposeConvertProcess(graph, remaining.front()), "TransposeConvertProcess failed");
122	      remaining = FindTransposeNodes(graph);
123	    }
124	    return af::SUCCESS;
125	  }
126	
127	  if (transpose_nodes.size() == 1UL) {
128	    // 单个Transpose：生成保留和消除两套模板，通过打分选择
129	    graphs.emplace_back(graph);
130	
131	    ascir::ImplGraph optimized_graph((graph.GetName() + "_group_transpose").c_str());
132	    optimized_graph.CopyFrom(graph);
133	
134	    auto transpose_node = FindTransposeNodes(optimized_graph).front();
135	    GE_CHK_STATUS_RET(TransposeConvertProcess(optimized_graph, transpose_node), "TransposeConvertProcess failed");
136	    graphs.emplace_back(optimized_graph);
137	
138	    transpose_node = FindTransposeNodes(graphs[0]).front();
139	    score_functions.resize(2U);
140	    GE_CHK_STATUS_RET(GenerateScoreFuncForUbReorder(graph, transpose_node, score_functions[0]),
141	                      "Failed to generate score func");
142	  } else {
143	    // 多个Transpose：仅生成消除模板，将所有Transpose行为推到load上
144	    ascir::ImplGraph optimized_graph((graph.GetName() + "_group_transpose").c_str());
145	    optimized_graph.CopyFrom(graph);
146	
147	    auto remaining = FindTransposeNodes(optimized_graph);
148	    while (!remaining.empty()) {
149	      GE_CHK_STATUS_RET(TransposeConvertProcess(optimized_graph, remaining.front()), "TransposeConvertProcess failed");
150	      remaining = FindTransposeNodes(optimized_graph);
151	    }
152	    graphs.emplace_back(optimized_graph);
153	  }
154	
155	  return af::SUCCESS;
156	}
157	
158	Status TransposeFusionCaseGenerator::GenerateScoreFuncForUbReorder(const ascir::HintGraph &graph,
159	                                                                   const af::AscNodePtr &transpose_node,
160	                                                                   std::string &score_func) {
161	  return TransposeScoreFunctionGenerator(graph, transpose_node).Generate(score_func);
162	}
163	
164	TransposeScoreFunctionGenerator::TransposeScoreFunctionGenerator(const ascir::HintGraph &graph,
165	                                                                 af::AscNodePtr transpose_node)
166	    : graph_(&graph), transpose_node_(std::move(transpose_node)) {}
167	
168	Status TransposeScoreFunctionGenerator::ParseRepeat() {
169	  const auto last_idx = transpose_node_->inputs[0].attr.axis.size() - 1;
170	  repeat_ = transpose_node_->inputs[0].attr.repeats[last_idx];
171	  return af::SUCCESS;
172	}
173	
174	Status TransposeScoreFunctionGenerator::Generate(std::string &score_func) {
175	  GE_CHK_STATUS_RET(ParseRepeat());
176	  ss_ << "int32_t CalcScore(const AutofuseTilingData &tiling_data) {" << std::endl;
177	  int32_t score = 0;
178	
179	  GE_CHK_STATUS_RET(GetScoreByExpr(score));
180	  GenerateReturnValue(score);
181	  score_func = ss_.str();
182	  return af::SUCCESS;
183	}
184	
185	void TransposeScoreFunctionGenerator::GenerateReturnValue(const int32_t score) {
186	  ss_ << "  return " << score << ";" << std::endl;
187	  ss_ << "}" << std::endl;
188	}
189	
190	Status TransposeScoreFunctionGenerator::GetScoreByExpr(int32_t &score) const {
191	  // 使用表达式值获取分数值
192	  const auto last_idx = transpose_node_->inputs[0].attr.axis.size() - 1;
193	  const auto &input_tail_axis = transpose_node_->inputs[0].attr.axis[last_idx];
194	  const auto &output_tail_axis = transpose_node_->outputs[0].attr.axis[last_idx];
195	
196	  if (input_tail_axis != output_tail_axis) {
197	    score = 1;
198	    return af::SUCCESS;
199	  }
200	  // 非尾轴转置需要根据尾轴大小确定分数
201	  int32_t dim = -1;
202	  GE_ASSERT_TRUE(repeat_.GetHint(dim), "Failed to get int value, expr = %s",
203	                 af::SymbolicUtils::ToString(repeat_).c_str());
204	  const auto limited_size = kTransposeNoNeedUBConvertSize / GetSizeByDataType(transpose_node_->inputs[0].attr.dtype);
205	  score = dim < limited_size ? 1 : -1;
206	  return af::SUCCESS;
207	}
208	}  // namespace optimize
209

