141	bool IsNotPartitionReduce(const af::AscNodePtr &reduce_node, size_t threshold) {
142	  std::queue<af::NodePtr> node_queue;
143	  size_t node_count = 0UL;
144	  std::unordered_set<const af::Node *> visited;
145	  visited.insert(reduce_node.get());
146	  for (const auto &reduce_out_node : reduce_node->GetOutNodes()) {
147	    node_queue.emplace(reduce_out_node);
148	    visited.insert(reduce_out_node.get());
149	  }
150	  while (!node_queue.empty()) {
151	    const auto current_node = node_queue.front();
152	    node_queue.pop();
153	
154	    if (current_node->GetInDataNodesSize() > 1UL) {
155	      for (const auto &in_current_node : current_node->GetInDataNodes()) {
156	        if (visited.find(in_current_node.get()) == visited.end()) {
157	          GELOGW("Node [%s] has multiple inputs, with input node [%s] not being a post-reduction node.",
158	                 current_node->GetNamePtr(), in_current_node->GetNamePtr());
159	          return false;
160	        }
161	      }
162	    }
163	
164	    node_count += 1UL;
165	    if (node_count > threshold) {
166	      GELOGW(
167	          "The total count of nodes after the reduce node[%s](including the store node) is above the threshold[%zu].",
168	          reduce_node->GetNamePtr(), threshold);
169	      return false;
170	    }
171	    const auto &asc_current_node = std::dynamic_pointer_cast<af::AscNode>(current_node);
172	    GE_ASSERT_NOTNULL(asc_current_node);
173	    if (af::ops::IsOps<af::ascir_op::Store>(asc_current_node) ||
174	        asc_current_node->attr.api.type == af::ApiType::kAPITypeBuffer) {
175	      continue;
176	    }
177	
178	    if (!ScheduleUtils::IsElewise(asc_current_node)) {
179	      GELOGW("The node[%s] after the reduce node[%s] is not elewise type.", asc_current_node->GetNamePtr(),
180	             reduce_node->GetNamePtr());
181	      return false;
182	    }
183	
184	    if (node_count > threshold - 1UL) {
185	      GELOGW("The count of nodes after the reduce node[%s] is above the threshold[%zu].", reduce_node->GetNamePtr(),
186	             threshold - 1UL);
187	      return false;
188	    }
189	
190	    for (const auto &next_node : current_node->GetOutAllNodes()) {
191	      if (visited.find(next_node.get()) == visited.end()) {
192	        visited.insert(next_node.get());
193	        node_queue.emplace(next_node);
194	      }
195	    }
196	  }
197	  return true;
198	}
