243	Status ReducePartitionCaseGenerator::GeneratorRCoreTask(ascir::HintGraph &optimize_graph,
244	                                                        std::vector<ScheduleTask> &tasks) const {
245	  std::vector<ScheduleTask> new_tasks;
246	  for (const auto &task : tasks) {
247	    if (task.reduce_type != ReduceTemplateType::kCommon) {
248	      continue;
249	    }
250	    if (HasArgMaxReduce(task)) {
251	      GELOGI("Task contains ArgMax reduce op, skip R-core template generation");
252	      continue;
253	    }
254	    std::vector<::ascir::ImplGraph> new_task_grouped_graphs;
255	    std::map<size_t, std::vector<size_t>> map;
256	    size_t phase_2_graph_size = 0;
257	    for (size_t i = 0; i < task.grouped_graphs.size(); i++) {
258	      GE_ASSERT_TRUE(IsGroupGraphLegal(task.grouped_graphs[i]));
259	      if (!HasReduce(task.grouped_graphs[i])) {
260	        ::ascir::ImplGraph graph((task.grouped_graphs[i].GetName() + "_r_multicore").c_str());
261	        graph.CopyFrom(task.grouped_graphs[i]);
262	        new_task_grouped_graphs.emplace_back(std::move(graph));
263	        continue;
264	      }
265	      ascir::ImplGraph phase_graph((task.grouped_graphs[i].GetName() + "_r_multicore_phase_graph").c_str());
266	      phase_graph.CopyFrom(task.grouped_graphs[i]);
267	      af::AscNodePtr reduce_node;
268	      for (auto node : phase_graph.GetAllNodes()) {
269	        if (ScheduleUtils::IsReduce(node)) {
270	          reduce_node = node;
271	          break;
272	        }
273	      }
274	      GE_CHECK_NOTNULL(reduce_node);
275	      GE_ASSERT_TRUE(IsNotPartitionReduce(reduce_node, NODE_COUNT_AFTER_REDUCE));
276	      ascir::ImplGraph phase_1_graph((task.grouped_graphs[i].GetName() + "_r_multicore_phase_1_graph").c_str());
277	      ascir::ImplGraph phase_2_graph((task.grouped_graphs[i].GetName() + "_r_multicore_phase_2_graph").c_str());
278	      GE_CHK_STATUS_RET(RMulticorePhase2Graph(phase_2_graph, phase_1_graph, phase_graph, reduce_node).Construct());
279	      ascir::utils::DumpGraph(phase_2_graph, "phase2graph_construct");
280	      new_task_grouped_graphs.emplace_back(std::move(phase_1_graph));
281	      new_task_grouped_graphs.emplace_back(std::move(phase_2_graph));
282	      map[i + phase_2_graph_size] = {i + phase_2_graph_size + 1};
283	      phase_2_graph_size++;
284	    }
285	    if (phase_2_graph_size == 0) {
286	      continue;
287	    }
288	    ScheduleTask new_task{optimize_graph, new_task_grouped_graphs, task.score_func, map, ReduceTemplateType::kRCore};
289	    new_tasks.push_back(new_task);
290	  }
291	  tasks.insert(tasks.end(), new_tasks.begin(), new_tasks.end());
292	  return ge::GRAPH_SUCCESS;
293	}
