296	                                                   const OptimizerOptions &options) {
297	  (void)options;
298	  const af::AscNodePtr indirect_load = ascgen_utils::indirect_load::FindIndirectLoadNode(optimize_graph);
299	  if (indirect_load != nullptr && ascgen_utils::indirect_load::HasPostReduceConsumer(indirect_load)) {
300	    GELOGI("Graph %s has indirect load with post reduce consumer, skip reduce task generation.",
301	           optimize_graph.GetName().c_str());
302	    return ge::GRAPH_SUCCESS;
303	  }
304	  const bool force_all_load = ShouldForceAllLoad(optimize_graph);
305	  GELOGI("Graph %s force AllLoad = %d, begin to generate reduce tasks.", optimize_graph.GetName().c_str(),
306	         static_cast<int32_t>(force_all_load));
307	  if (!force_all_load || options.graph_type != GraphType::kFusedAscBackend) {
308	    GE_CHK_STATUS_RET(GeneratorGeneralTask(optimize_graph, tasks));
309	    GELOGI("After GeneralTask, graph %s has %zu task(s).", optimize_graph.GetName().c_str(), tasks.size());
310	  }
311	  if (!force_all_load) {
312	    GE_CHK_STATUS_RET(GeneratorRCoreTask(optimize_graph, tasks));
313	    GELOGI("After RCoreTask, graph %s has %zu task(s).", optimize_graph.GetName().c_str(), tasks.size());
314	  }
315	  GE_CHK_STATUS_RET(GeneratorAllLoadTask(optimize_graph, tasks));
316	  GELOGI("After AllLoadTask, graph %s has %zu task(s).", optimize_graph.GetName().c_str(), tasks.size());
317	  return ge::GRAPH_SUCCESS;
318	}
