326	bool ReducePartitionCaseGenerator::ShouldForceAllLoad(ascir::HintGraph &graph) {
327	  if (!IsGroupGraphLegal(graph)) {
328	    return true;
329	  }
330	
331	  ascir::ImplGraph impl_graph(graph.GetName().c_str());
332	  impl_graph.CopyFrom(graph);
333	  node_order_.clear();
334	  auto loop_start_end = FindNormLoops(impl_graph);
335	  if (!loop_start_end.empty()) {
336	    return true;
337	  }
338	
339	  return false;
340	}
