342	Status ReducePartitionCaseGenerator::GenerateGeneralCase(ascir::HintGraph &graph, std::vector<ascir::ImplGraph> &graphs,
343	                                                         std::vector<std::string> &score_functions) {
344	  if (!HasReduce(graph)) {
345	    return ge::GRAPH_SUCCESS;
346	  }
347	  ascir::ImplGraph optimize_graph(graph.GetName().c_str());
348	  optimize_graph.CopyFrom(graph);
349	
350	  node_order_.clear();
351	  auto loop_start_end = FindNormLoops(optimize_graph);
352	  std::sort(
353	      loop_start_end.begin(), loop_start_end.end(),
354	      [](const std::pair<af::AscNodePtr, af::AscNodePtr> &lhs, const std::pair<af::AscNodePtr, af::AscNodePtr> &rhs) {
355	        return lhs.second->GetOpDescBarePtr()->GetId() < rhs.second->GetOpDescBarePtr()->GetId();
356	      });
357	
358	  GELOGI("FindNormLoops got %zu loop(s):", loop_start_end.size());
359	  for (size_t i = 0UL; i < loop_start_end.size(); i++) {
360	    GELOGI("  loop[%zu] start=%s(id=%lld) end=%s(id=%lld)", i, loop_start_end[i].first->GetName().c_str(),
361	           loop_start_end[i].first->GetOpDescBarePtr()->GetId(), loop_start_end[i].second->GetName().c_str(),
362	           loop_start_end[i].second->GetOpDescBarePtr()->GetId());
363	  }
364	
365	  // reduce 后融合切分
366	  GE_CHK_STATUS_RET(ReducePartitionPostFusion(optimize_graph));
367	  ascir::utils::DumpGraph(optimize_graph, "after_post_fusion");
368	
369	  // 按照前面获取的环路起点、终点，进行norm的切分
370	  GE_CHK_STATUS_RET(PartitionNorm(optimize_graph, loop_start_end));
371	  ascir::utils::DumpGraph(optimize_graph, "after_partition_norm");
372	
373	  // reduce 多引用结构需要切分的，切分开
374	  GE_CHK_STATUS_RET(ReducePartitionMultipleCitations(optimize_graph));
375	  ascir::utils::DumpGraph(optimize_graph, "after_multiple_citations");
376	
377	  if (partition_) {
378	    std::sort(node_order_.begin(), node_order_.end(), [](const af::AscNodePtr &lhs, af::AscNodePtr &rhs) {
379	      return lhs->GetOpDescBarePtr()->GetId() < rhs->GetOpDescBarePtr()->GetId();
380	    });
381	
382	    graphs.emplace_back(optimize_graph);
383	    score_functions.resize(graphs.size());
384	  } else {
385	    node_order_.clear();
386	    graphs.emplace_back(graph);
387	  }
388	  return ge::GRAPH_SUCCESS;
389	}
