402	Status ReducePartitionCaseGenerator::ReducePartitionMultipleCitations(ascir::ImplGraph &impl_graph) {
403	  if (IsGroupGraphLegal(impl_graph)) {
404	    return ge::GRAPH_SUCCESS;
405	  }
406	  std::vector<af::AscNodePtr> multi_output_nodes;
407	  for (auto node : impl_graph.GetAllNodes()) {
408	    if (node->GetOutNodes().size() > 1UL) {
409	      multi_output_nodes.emplace_back(node);
410	    }
411	  }
412	  std::sort(multi_output_nodes.begin(), multi_output_nodes.end(), [](const af::AscNodePtr &lhs, af::AscNodePtr &rhs) {
413	    return lhs->GetOpDescBarePtr()->GetId() > rhs->GetOpDescBarePtr()->GetId();
414	  });
415	  for (auto node : multi_output_nodes) {
416	    std::set<af::AscNodePtr> reduce_nodes;
417	    for (const auto &output_node : node->GetOutNodes()) {
418	      af::AscNodePtr out_asc_node = std::dynamic_pointer_cast<af::AscNode>(output_node);
419	      if (af::AscNodePtr reduce_node = nullptr; FindOutputReduce(out_asc_node, reduce_node)) {
420	        if (!reduce_nodes.empty() && reduce_nodes.find(reduce_node) == reduce_nodes.end()) {
421	          PartitionByNode(node, out_asc_node, impl_graph);
422	        }
423	        reduce_nodes.emplace(reduce_node);
424	      }
425	    }
426	  }
427	  return ge::GRAPH_SUCCESS;
428	}
