430	bool ReducePartitionCaseGenerator::FindOutputReduce(const af::AscNodePtr &node, af::AscNodePtr &reduce_node) {
431	  if (ScheduleUtils::IsReduce(node)) {
432	    reduce_node = node;
433	    return true;
434	  }
435	  bool output_has_reduce = false;
436	  if (node->GetOutNodes().empty()) {
437	    return output_has_reduce;
438	  }
439	  for (const auto &output_node : node->GetOutNodes()) {
440	    auto output_asc_node = std::dynamic_pointer_cast<af::AscNode>(output_node);
441	    output_has_reduce = output_has_reduce || FindOutputReduce(output_asc_node, reduce_node);
442	  }
443	  return output_has_reduce;
444	}
