446	Status ReducePartitionCaseGenerator::PartitionReduceNode(af::AscNodePtr &src_node, ascir::ImplGraph &impl_graph) {
447	  partition_ = true;
448	  node_order_.emplace_back(src_node);
449	  af::ascir_op::Workspace workspace_pre((src_node->GetName() + "_Workspace").c_str());
450	  af::ascir_op::Workspace workspace_post((src_node->GetName() + "_Workspace").c_str());
451	  af::ascir_op::Load load((src_node->GetName() + "_Load").c_str());
452	  af::ascir_op::Store store((src_node->GetName() + "_Store").c_str());
453	  auto workspace_pre_node = impl_graph.AddNode(workspace_pre);
454	  auto workspace_post_node = impl_graph.AddNode(workspace_post);
455	  auto load_node = impl_graph.AddNode(load);
456	  auto store_node = impl_graph.AddNode(store);
457	  GE_CHK_STATUS_RET(DoCopyAscNodeTensorAttr(src_node, load_node));
458	  GE_CHK_STATUS_RET(DoCopyAscNodeTensorAttr(src_node, store_node));
459	  GE_CHK_STATUS_RET(DoCopyWorkspaceTensorAttr(store_node, workspace_pre_node));
460	  GE_CHK_STATUS_RET(DoCopyWorkspaceTensorAttr(load_node, workspace_post_node));
461	  for (const auto &out_anchor : src_node->GetAllOutDataAnchors()) {
462	    GE_CHECK_NOTNULL(out_anchor, "Out data anchor is null, node:%s.", src_node->GetNamePtr());
463	    for (const auto &peer_in_anchor : out_anchor->GetPeerInDataAnchors()) {
464	      GE_CHECK_NOTNULL(peer_in_anchor);
465	      auto dst_node = peer_in_anchor->GetOwnerNode();
466	      GE_CHECK_NOTNULL(dst_node, "peer node is null, src node: %s", src_node->GetNamePtr());
467	      // remove src->dst
468	      GE_CHK_STATUS_RET(af::GraphUtils::RemoveEdge(src_node->GetOutAnchor(out_anchor->GetIdx()),
469	                                                   dst_node->GetInAnchor(peer_in_anchor->GetIdx())));
470	      GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(load_node->GetOutAnchor(out_anchor->GetIdx()),
471	                                                dst_node->GetInAnchor(peer_in_anchor->GetIdx())));
472	    }
473	  }
474	  // add src->store->workspace_pre_node
475	  GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(src_node->GetOutAnchor(0UL), store_node->GetInAnchor(0UL)));
476	  GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(store_node->GetOutAnchor(0UL), workspace_pre_node->GetInAnchor(0UL)));
477	  // add workspace_post_node->load->dst
478	  GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(workspace_post_node->GetOutAnchor(0UL), load_node->GetInAnchor(0UL)));
479	  return ge::GRAPH_SUCCESS;
480	}
