482	Status ReducePartitionCaseGenerator::ReducePartitionPostFusion(ascir::ImplGraph &impl_graph) {
483	  for (auto node : impl_graph.GetAllNodes()) {
484	    if (ScheduleUtils::IsReduce(node)) {
485	      if (IsNotPartitionReduce(node, NODE_COUNT_AFTER_REDUCE)) {
486	        continue;
487	      }
488	      GE_CHK_STATUS_RET(PartitionReduceNode(node, impl_graph));
489	    }
490	  }
491	  return ge::GRAPH_SUCCESS;
492	}
