494	Status ReducePartitionCaseGenerator::PartitionLoadNode(af::AscNodePtr &src_load_node, af::AscNodePtr &dst_node,
495	                                                       ascir::ImplGraph &impl_graph) {
496	  auto load_input_node = src_load_node->GetInNodes().at(0UL);
497	  auto load_input_asc_node = std::dynamic_pointer_cast<af::AscNode>(load_input_node);
498	  GE_ASSERT_TRUE(af::ops::IsOps<af::ascir_op::Data>(load_input_asc_node) ||
499	                 af::ops::IsOps<af::ascir_op::Workspace>(load_input_asc_node));
500	  af::ascir_op::Load load(("copy_from_" + src_load_node->GetName()).c_str());
501	
502	  af::AscNodePtr new_load_input_node;
503	  if (af::ops::IsOps<af::ascir_op::Data>(load_input_asc_node)) {
504	    af::ascir_op::Data data(("copy_from_" + load_input_asc_node->GetName()).c_str());
505	    new_load_input_node = impl_graph.AddNode(data);
506	  } else {
507	    af::ascir_op::Workspace workspace(("copy_from_" + load_input_asc_node->GetName()).c_str());
508	    new_load_input_node = impl_graph.AddNode(workspace);
509	  }
510	  auto load_node = impl_graph.AddNode(load);
511	  DoCopyAscNodeTensorAttr(load_input_asc_node, new_load_input_node);
512	  DoCopyAscNodeTensorAttr(src_load_node, load_node);
513	  for (const auto &out_anchor : src_load_node->GetAllOutDataAnchors()) {
514	    GE_CHECK_NOTNULL(out_anchor, "Out data anchor is null, node:%s.", src_load_node->GetNamePtr());
515	    for (const auto &peer_in_anchor : out_anchor->GetPeerInDataAnchors()) {
516	      GE_CHECK_NOTNULL(peer_in_anchor);
517	      GE_CHECK_NOTNULL(peer_in_anchor->GetOwnerNodeBarePtr(), "Peer in node:%s is null", src_load_node->GetNamePtr());
518	      if (peer_in_anchor->GetOwnerNodeBarePtr() == dst_node.get()) {
519	        // remove load->dst
520	        GE_CHK_STATUS_RET(af::GraphUtils::RemoveEdge(src_load_node->GetOutAnchor(out_anchor->GetIdx()),
521	                                                     dst_node->GetInAnchor(peer_in_anchor->GetIdx())));
522	        // add new_load_input->new_load->dst
523	        GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(new_load_input_node->GetOutAnchor(0UL), load_node->GetInAnchor(0UL)));
524	        GE_CHK_STATUS_RET(
525	            af::GraphUtils::AddEdge(load_node->GetOutAnchor(0UL), dst_node->GetInAnchor(peer_in_anchor->GetIdx())));
526	        return ge::GRAPH_SUCCESS;
527	      }
528	    }
529	  }
530	  return ge::GRAPH_SUCCESS;
531	}
