584	    auto load_node = impl_graph.AddNode(load);
585	    auto store_node = impl_graph.AddNode(store);
586	    GE_CHK_STATUS_RET(DoCopyAscNodeOutputTensorAttr(src_node, load_node, out_anchor->GetIdx()));
