590	    for (const auto &peer_in_anchor : out_anchor->GetPeerInDataAnchors()) {
591	      GE_CHECK_NOTNULL(peer_in_anchor);
592	      GE_CHECK_NOTNULL(peer_in_anchor->GetOwnerNodeBarePtr(), "Peer in node:%s is null", src_node->GetNamePtr());
593	      if (peer_in_anchor->GetOwnerNodeBarePtr() == dst_node.get()) {
