611	bool ReducePartitionCaseGenerator::IsInputNodePartitioned(const std::shared_ptr<af::Node> &start,
612	                                                          const std::shared_ptr<af::Node> &node) {
613	  // 向前找 start 节点，如找到则未经过切分，到根节点未找到则已切分或不需要切分
614	  if (node == start) {
615	    return false;
616	  }
617	  bool partitioned = true;
618	  if (node->GetInNodes().empty()) {
619	    return partitioned;
620	  }
621	  for (const auto &in_node : node->GetInNodes()) {
622	    partitioned = partitioned && IsInputNodePartitioned(start, in_node);
623	  }
624	  return partitioned;
625	}
