627	std::vector<std::pair<af::AscNodePtr, af::AscNodePtr>> ReducePartitionCaseGenerator::FindNormLoops(
628	    ascir::ImplGraph &graph) {
629	  std::vector<std::pair<af::AscNodePtr, af::AscNodePtr>> loop_start_end;
630	  for (auto node : graph.GetAllNodes()) {
631	    if (node->GetOutDataNodes().empty()) {
632	      node_order_.emplace_back(node);
633	    }
634	    if (node->GetOutNodes().size() <= 1UL) {
635	      continue;
636	    }
637	    std::vector<af::AscNodePtr> loop_ends;
638	    FindNormLoop(node, loop_ends);
639	    for (const auto &end : loop_ends) {
640	      loop_start_end.emplace_back(node, end);
641	    }
642	  }
643	  return loop_start_end;
644	}
645	
646	Status ReducePartitionCaseGenerator::FindNormLoop(const af::AscNodePtr &start, std::vector<af::AscNodePtr> &ends) {
647	  std::set<af::NodePtr> visited{start};
648	  std::list<af::NodePtr> next_nodes{start};
649	  while (!next_nodes.empty()) {
650	    const auto node = next_nodes.front();
651	    next_nodes.pop_front();
652	    for (auto &out_node : node->GetOutDataNodes()) {
653	      if (visited.find(out_node) == visited.cend()) {
654	        next_nodes.emplace_back(out_node);
655	        visited.emplace(out_node);
656	      } else {
657	        auto asc_node = std::dynamic_pointer_cast<af::AscNode>(out_node);
658	        ends.emplace_back(asc_node);
659	      }
660	    }
661	  }
662	  ends.erase(std::remove_if(ends.begin(), ends.end(),
663	                            [start, this](const af::AscNodePtr &end) { return !IsNorm(start, end); }),
664	             ends.end());
665	  return ge::GRAPH_SUCCESS;
666	}
667	
668	void ReducePartitionCaseGenerator::FindAllPath(const af::AscNodePtr &start, const af::AscNodePtr &end,
669	                                               std::vector<af::AscNodePtr> &path,
670	                                               std::vector<std::vector<af::AscNodePtr>> &all_paths) {
671	  // 需保证图为有向无环图
672	  path.emplace_back(start);
673	  if (start == end) {
674	    all_paths.emplace_back(path);
675	  }
676	  for (const auto &out_node : start->GetOutNodes()) {
677	    const auto asc_node = std::dynamic_pointer_cast<af::AscNode>(out_node);
678	    FindAllPath(asc_node, end, path, all_paths);
679	  }
680	  path.pop_back();
681	}
682	
683	bool ReducePartitionCaseGenerator::IsNorm(const af::AscNodePtr &start, const af::AscNodePtr &end) {
684	  std::vector<af::AscNodePtr> path;
685	  std::vector<std::vector<af::AscNodePtr>> all_paths;
686	  FindAllPath(start, end, path, all_paths);
687	  bool is_norm = false;
688	  std::set<af::AscNodePtr> end_in_nodes;
689	  for (const auto &path_temp : all_paths) {
690	    for (const auto &node : path_temp) {
691	      if (ScheduleUtils::IsReduce(node)) {
692	        is_norm = true;
693	        break;
694	      }
695	    }
696	    end_in_nodes.insert(path_temp.at(path_temp.size() - TWO));
697	  }
698	  return is_norm && end_in_nodes.size() > 1;
699	}
