701	Status ReducePartitionCaseGenerator::PartitionNorm(
702	    ascir::ImplGraph &impl_graph, std::vector<std::pair<af::AscNodePtr, af::AscNodePtr>> &loop_start_end) {
703	  for (auto loop : loop_start_end) {
704	    for (auto &in_node : loop.second->GetInNodes()) {
705	      if (IsInputNodePartitioned(loop.first, in_node)) {
706	        continue;
707	      }
708	      af::AscNodePtr src_node = std::dynamic_pointer_cast<af::AscNode>(in_node);
709	      GELOGI("PartitionNorm: loop start=%s end=%s, partition src_node=%s -> dst(loop.end)=%s",
710	             loop.first->GetName().c_str(), loop.second->GetName().c_str(), src_node->GetName().c_str(),
711	             loop.second->GetName().c_str());
712	      GE_CHK_STATUS_RET(PartitionByNode(src_node, loop.second, impl_graph));
713	    }
714	  }
715	  return ge::GRAPH_SUCCESS;
716	}
