727	bool ReducePartitionCaseGenerator::HasArgMaxReduce(const ScheduleTask &task) {
728	  for (const auto &grouped_graph : task.grouped_graphs) {
729	    if (!HasReduce(grouped_graph)) {
730	      continue;
731	    }
732	    for (const auto &node : grouped_graph.GetAllNodes()) {
733	      if (ScheduleUtils::IsReduce(node) && node->GetType() == "ArgMax") {
734	        return true;
735	      }
736	    }
737	  }
738	  return false;
739	}
