741	// 全载模板支持历史 AR/ARA 类短轴场景，并额外支持 AA...AR 尾轴 reduce 场景。
742	bool ReducePartitionCaseGenerator::CanFullLoadReduceFuse(const ascir::ImplGraph &impl_graph) {
743	  for (const auto &node : impl_graph.GetAllNodes()) {
744	    if (!ScheduleUtils::IsReduce(node)) {
745	      continue;
746	    }
747	    std::vector<ascir::SizeExpr> input_repeats = node->inputs[0].attr.repeats;
748	    std::vector<ascir::SizeExpr> output_repeats = node->outputs[0].attr.repeats;
749	    GE_ASSERT_TRUE(input_repeats.size() == output_repeats.size());
750	    if (output_repeats.empty()) {
751	      return false;
752	    }
753	
754	    if (!IsLegacyFullLoadReduce(input_repeats, output_repeats) &&
755	        !IsTailReduceFullLoad(node, input_repeats, output_repeats)) {
756	      return false;
757	    }
758	  }
759	
760	  return true;
761	}
