763	bool ReducePartitionCaseGenerator::IsGroupGraphLegal(const ascir::ImplGraph &impl_graph) {
764	  int reduce_count = 0;
765	  for (const auto &node : impl_graph.GetAllNodes()) {
766	    if (ScheduleUtils::IsReduce(node)) {
767	      reduce_count += 1;
768	    }
769	  }
770	  return reduce_count <= 1;
