773	Status RMulticorePhase2Graph::Construct() {
774	  GE_ASSERT_TRUE(reducers.find(reduce_node->GetType()) != reducers.end());
775	  ReduceType phase2graph_reduce =
776	      reducers.find(reduce_node->GetType())
777	          ->second((phase2graph.GetName() + "_" + reduce_node->GetName() + "_reduce").c_str());
778	  std::visit([](auto &&reduce_op) { reduce_op.attr.sched.axis = {0, 1}; }, phase2graph_reduce);
779	
780	  // 对于ArgMax，需要在调用CompletePhaseGraph之前保存输入dtype（value类型）
781	  // 因为CompletePhaseGraph会调用PartitionByReduce，后者会删除reduce_node
782	  af::AscTensorDataType argmax_input_dtype;
783	  if (reduce_node->GetType() == "ArgMax") {
784	    GE_ASSERT_TRUE(!reduce_node->inputs().empty(), "ArgMax node should have at least 1 input");
785	    argmax_input_dtype = reduce_node->inputs[0].attr.dtype;
786	  }
787	
788	  GE_CHK_STATUS_RET(CompletePhaseGraph(phase2graph_reduce));
789	  GE_CHK_STATUS_RET(CreateVarAxis());
790	
791	  auto workspace_node = phase2graph.FindNode((phase2graph.GetName() + "_workspace").c_str());
792	  GE_ASSERT_NOTNULL(workspace_node);
793	  workspace_node->attr.sched.axis = {0, 1};
794	  // 对于ArgMax，workspace存储的是value（输入类型），不是index（输出类型）
795	  af::AscTensorDataType workspace_dtype;
796	  if (reduce_node->GetType() == "ArgMax") {
797	    workspace_dtype = argmax_input_dtype;
798	  } else {
799	    workspace_dtype = reduce_node->outputs[0].attr.dtype;
800	  }
801	  GE_CHK_STATUS_RET(CompleteNodeAttr(workspace_node, true, workspace_dtype));
802	  auto load_node = phase2graph.FindNode((phase2graph.GetName() + "_load").c_str());
803	  GE_ASSERT_NOTNULL(load_node);
804	  load_node->attr.sched.axis = {0, 1};
805	  // load从workspace读取，dtype与workspace相同
806	  GE_CHK_STATUS_RET(CompleteNodeAttr(load_node, true, workspace_dtype));
807	
808	  // ArgMax特殊处理：需要设置load_index_node和workspace_index_node的属性
809	  GE_CHK_STATUS_RET(SetupArgMaxIndexNodes(reduce_node, phase2graph));
810	
811	  auto reduce_node_parse2graph =
812	      phase2graph.FindNode((phase2graph.GetName() + "_" + reduce_node->GetName() + "_reduce").c_str());
813	  GE_ASSERT_NOTNULL(reduce_node_parse2graph);
814	  std::set<af::NodePtr> visited{reduce_node_parse2graph};
815	  std::list<af::NodePtr> next_nodes{reduce_node_parse2graph};
816	  while (!next_nodes.empty()) {
817	    const auto node = next_nodes.front();
818	    next_nodes.pop_front();
819	    auto asc_node = std::dynamic_pointer_cast<af::AscNode>(node);
820	    asc_node->attr.sched.axis = {0, 1};
821	    GE_CHK_STATUS_RET(CompleteNodeAttr(asc_node, false, asc_node->outputs[0].attr.dtype));
822	    for (auto &out_node : node->GetOutDataNodes()) {
823	      if (visited.find(out_node) == visited.cend()) {
824	        next_nodes.emplace_back(out_node);
825	        visited.emplace(out_node);
826	      }
827	    }
828	  }
829	  return ge::GRAPH_SUCCESS;
830	}
