832	Status RMulticorePhase2Graph::CreateVarAxis() {
833	  // 创建符号：A轴符号：s1，R轴符号：s2
834	  auto compute_graph = af::AscGraphUtils::GetComputeGraph(phase2graph);
835	  GE_ASSERT_NOTNULL(compute_graph);
836	  auto attr = compute_graph->GetOrCreateAttrsGroup<af::AscGraphAttr>();
