838	  attr->axis.clear();
839	  attr->size_vars.clear();
840	  Rm_org_size = phase2graph.CreateSizeVar("Rm_org_size");
841	  A_org_size = phase2graph.CreateSizeVar("A_org_size");
842	  // 创建轴：a，r
843	  phase2graph.CreateAxis("Rm", Rm_org_size);
844	  phase2graph.CreateAxis("A", A_org_size);
845	  return ge::GRAPH_SUCCESS;
846	}
