848	Status RMulticorePhase2Graph::CompleteNodeAttr(af::AscNodePtr &node, bool before_reduce,
849	                                               const af::AscTensorDataType &data_type) {
850	  node->outputs[0].attr.dtype = data_type;
851	  node->outputs[0].attr.axis = {0, 1};
852	  if (before_reduce) {
853	    node->outputs[0].attr.strides = {A_org_size, af::ops::One};
854	    node->outputs[0].attr.repeats = {Rm_org_size, A_org_size};
855	  } else {
856	    node->outputs[0].attr.strides = {af::ops::Zero, af::ops::One};
857	    node->outputs[0].attr.repeats = {af::ops::One, A_org_size};
858	  }
859	  return ge::GRAPH_SUCCESS;
860	}
