888	Status RMulticorePhase2Graph::CompletePhaseGraph(ReduceType &phase2graph_reduce) {
889	  std::vector<af::AscNodePtr> node_order;
890	  GE_ASSERT_GRAPH_SUCCESS(PartitionByReduce(phase_graph, phase2graph_reduce, node_order));
891	  GE_ASSERT_GRAPH_SUCCESS(SetNodeOrder(node_order));
892	  std::vector<::ascir::ImplGraph> sub_optimize_graphs;
893	  GE_ASSERT_GRAPH_SUCCESS(
894	      ScheduleGroupGraphPartitioner::PartitionByConnectivity(phase_graph, sub_optimize_graphs, node_order));
895	  GE_ASSERT_EQ(sub_optimize_graphs.size(), 2UL);
896	  phase1graph.CopyFrom(sub_optimize_graphs[0]);
897	  phase2graph.CopyFrom(sub_optimize_graphs[1]);
898	  return ge::GRAPH_SUCCESS;
899	}
