901	// 辅助函数：设置ArgMaxMultiRPhase1的输出属性
902	// ArgMaxMultiRPhase1有2个输出：output[0]=value(T类型), output[1]=index(DT_INT64)
903	// value的shape从原始ArgMax输出复制，dtype从输入复制
904	// index的shape从原始ArgMax输出复制，dtype固定为DT_INT64
905	static Status SetupArgMaxPhase1OutputAttrs(const af::AscNodePtr &phase1_node, const af::AscTensorAttr &input_attr,
906	                                           const af::AscTensorAttr &output_attr) {
907	  // 设置输出0（value）：shape从argmax_node输出复制，dtype从输入复制
908	  {
909	    auto op_desc = phase1_node->GetOpDesc();
910	    GE_CHECK_NOTNULL(op_desc->MutableOutputDesc(0));
911	    auto tensor_attr_group = op_desc->MutableOutputDesc(0)->GetOrCreateAttrsGroup<af::AscTensorAttr>();
912	    GE_ASSERT_NOTNULL(tensor_attr_group);
913	    // 复制shape等属性，但dtype使用输入的类型
914	    *tensor_attr_group = output_attr;
915	    tensor_attr_group->dtype = input_attr.dtype;
916	  }
917	
918	  // 设置输出1（index）：shape和格式等从输出0复制，dtype固定为DT_INT64
919	  {
920	    auto op_desc = phase1_node->GetOpDesc();
921	    GE_CHECK_NOTNULL(op_desc->MutableOutputDesc(1));
922	    auto tensor_attr_group = op_desc->MutableOutputDesc(1)->GetOrCreateAttrsGroup<af::AscTensorAttr>();
923	    GE_ASSERT_NOTNULL(tensor_attr_group);
924	    // 使用之前保存的output_attr，而不是访问phase1_node->outputs[0]
925	    *tensor_attr_group = output_attr;
926	    tensor_attr_group->dtype = ge::DT_INT64;
927	  }
928	  return ge::GRAPH_SUCCESS;
929	}
