931	// 辅助函数：复制节点级别的属性（sched、ir_attr等）
932	static void CopyNodeLevelAttrs(const af::AscNodePtr &dst_node, const af::AscNodePtr &src_node) {
933	  auto dst_op_desc = dst_node->GetOpDesc();
934	  auto dst_asc_node_attr = dst_op_desc->GetOrCreateAttrsGroup<af::AscNodeAttr>();
935	  auto src_op_desc = src_node->GetOpDesc();
936	  auto src_asc_node_attr = src_op_desc->GetOrCreateAttrsGroup<af::AscNodeAttr>();
937	  if (src_asc_node_attr != nullptr && dst_asc_node_attr != nullptr) {
938	    dst_asc_node_attr->sched = src_asc_node_attr->sched;
939	    if (src_asc_node_attr->ir_attr) {
940	      dst_asc_node_attr->ir_attr = src_asc_node_attr->ir_attr->Clone();
941	    }
942	  }
943	}
