945	// R轴分核时，在阶段1将ArgMax替换为ArgMaxMultiRPhase1
946	Status ReplaceArgMaxInPhase1(ascir::ImplGraph &phase_graph, const af::AscNodePtr &argmax_node,
947	                             af::AscNodePtr &store_node, af::AscNodePtr &workspace_pre_node,
948	                             af::AscNodePtr &workspace_pre_index_node_out) {
949	  // 创建ArgMaxMultiRPhase1节点替换原始ArgMax
950	  af::ascir_op::ArgMaxMultiRPhase1 argmax_phase1((argmax_node->GetName() + "_phase1").c_str());
951	  auto new_argmax_phase1_node = phase_graph.AddNode(argmax_phase1);
952	
953	  // 复制节点级别的属性（sched、ir_attr等）
954	  CopyNodeLevelAttrs(new_argmax_phase1_node, argmax_node);
955	
956	  // 保存输入和输出属性，因为后续重定向边会导致inputs被清空
957	  const auto &saved_input_attr = argmax_node->inputs[0].attr;
958	  const auto &saved_output_attr = argmax_node->outputs[0].attr;
959	
960	  // 为ArgMaxMultiRPhase1的两个输出设置正确的tensor属性
961	  (void)SetupArgMaxPhase1OutputAttrs(new_argmax_phase1_node, saved_input_attr, saved_output_attr);
962	
963	  // 将ArgMax节点的所有输入边重定向到ArgMaxMultiRPhase1节点
964	  for (const auto &in_anchor : argmax_node->GetAllInDataAnchors()) {
965	    GE_ASSERT_NOTNULL(in_anchor);
966	    auto src_anchor = in_anchor->GetPeerOutAnchor();
967	    if (src_anchor == nullptr) {
968	      continue;
969	    }
970	    GE_CHK_STATUS_RET(af::GraphUtils::RemoveEdge(src_anchor, in_anchor));
971	    GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(src_anchor, new_argmax_phase1_node->GetInAnchor(in_anchor->GetIdx())));
972	  }
973	
974	  // 为ArgMaxMultiRPhase1的第二个输出（index）创建额外的store节点
975	  // 注意：workspace_pre_index_node由调用方创建并传入，通过名称"_workspace_index"与Phase2的workspace_post_index关联
976	  af::ascir_op::Store store_index((argmax_node->GetName() + "_Store_index").c_str());
977	  auto new_store_index_node = phase_graph.AddNode(store_index);
978	
979	  // 复制tensor属性
980	  // 注意：argmax_phase1_node有两个输出，需要正确设置属性
981	
982	  // store_node接收argmax_phase1_node的输出0（value），类型应该是T（和输入相同）
983	  // 不能从argmax_node复制（argmax_node的输出是index，类型DT_INT64）
984	  // 注意：此时输入边已被重定向，argmax_node->inputs()可能为空，需要使用之前保存的属性
985	  {
986	    // 复制节点级别属性
987	    CopyNodeLevelAttrs(store_node, argmax_node);
988	    // 复制输出tensor属性：shape从output_attr复制，dtype从input_attr复制
989	    auto op_desc = store_node->GetOpDesc();
990	    auto tensor_attr_group = op_desc->MutableOutputDesc(0)->GetOrCreateAttrsGroup<af::AscTensorAttr>();
991	    GE_ASSERT_NOTNULL(tensor_attr_group);
992	    *tensor_attr_group = saved_output_attr;
993	    tensor_attr_group->dtype = saved_input_attr.dtype;
994	  }
995	
996	  // store_index_node接收argmax_phase1_node的输出1（index），类型是DT_INT64
997	  // 使用之前保存的属性设置，因为此时输入边已被重定向
998	  {
999	    // 复制节点级别属性
1000	    CopyNodeLevelAttrs(new_store_index_node, argmax_node);
1001	    // 复制输出tensor属性：使用保存的output_attr
1002	    auto op_desc = new_store_index_node->GetOpDesc();
1003	    auto tensor_attr_group = op_desc->MutableOutputDesc(0)->GetOrCreateAttrsGroup<af::AscTensorAttr>();
1004	    GE_ASSERT_NOTNULL(tensor_attr_group);
1005	    *tensor_attr_group = saved_output_attr;  // index的shape和argmax输出相同
1006	  }
1007	
1008	  // workspace_pre_node连接到store_node，从store_node复制属性
1009	  GE_ASSERT_GRAPH_SUCCESS(DoCopyWorkspaceTensorAttr(store_node, workspace_pre_node));
1010	  GE_ASSERT_GRAPH_SUCCESS(DoCopyWorkspaceTensorAttr(new_store_index_node, workspace_pre_index_node_out));
1011	
1012	  // 连接ArgMaxMultiRPhase1的第一个输出（value）到store节点
1013	  GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(new_argmax_phase1_node->GetOutAnchor(0UL), store_node->GetInAnchor(0UL)));
1014	  GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(store_node->GetOutAnchor(0UL), workspace_pre_node->GetInAnchor(0UL)));
1015	
1016	  // 连接ArgMaxMultiRPhase1的第二个输出（index）到store_index和workspace
1017	  GE_CHK_STATUS_RET(
1018	      af::GraphUtils::AddEdge(new_argmax_phase1_node->GetOutAnchor(1UL), new_store_index_node->GetInAnchor(0UL)));
1019	  GE_CHK_STATUS_RET(
1020	      af::GraphUtils::AddEdge(new_store_index_node->GetOutAnchor(0UL), workspace_pre_index_node_out->GetInAnchor(0UL)));
1021	
1022	  // 删除原始的ArgMax节点，避免"not visited"错误
1023	  // 输入边已被重定向到argmax_phase1_node
1024	  // 输出边将在PartitionByReduce中重定向到new_reduce_node
1025	  auto compute_graph = af::AscGraphUtils::GetComputeGraph(phase_graph);
1026	  GE_ASSERT_GRAPH_SUCCESS(af::GraphUtils::RemoveNodeWithoutRelink(compute_graph, argmax_node));
1027	
1028	  return ge::GRAPH_SUCCESS;
1029	}
