1063	// 设置ArgMax Phase2的所有属性
1064	static Status SetupArgMaxPhase2Attrs(const ReduceSavedNodeAttrInfo &saved_attr, const ReducePhase2Nodes &phase2_nodes,
1065	                                     const af::AscTensorAttr &reduce_input_attr,
1066	                                     const af::AscTensorAttr &reduce_output_attr, const ArgMaxIndexNodes &index_nodes) {
