1079	  // 设置输出（index）：shape和reduce输出相同，dtype为DT_INT64
1080	  {
1081	    auto op_desc = phase2_nodes.new_reduce_node->GetOpDesc();
1082	    GE_CHECK_NOTNULL(op_desc->MutableOutputDesc(0));
1083	    auto tensor_attr_group = op_desc->MutableOutputDesc(0)->GetOrCreateAttrsGroup<af::AscTensorAttr>();
1084	    GE_ASSERT_NOTNULL(tensor_attr_group);
1085	    *tensor_attr_group = reduce_output_attr;
1086	    tensor_attr_group->dtype = ge::DT_INT64;
1087	  }
1088	
1089	  // ArgMax特殊处理：先设置workspace和load的输出dtype
1090	  {
1091	    // 设置workspace_post和load的输出dtype为value类型
1092	    auto op_desc = phase2_nodes.workspace_post_node->GetOpDesc();
1093	    GE_CHECK_NOTNULL(op_desc->MutableOutputDesc(0));
1094	    auto tensor_attr_group = op_desc->MutableOutputDesc(0)->GetOrCreateAttrsGroup<af::AscTensorAttr>();
1095	    GE_ASSERT_NOTNULL(tensor_attr_group);
1096	    tensor_attr_group->dtype = reduce_input_attr.dtype;
1097	
1098	    op_desc = phase2_nodes.load_node->GetOpDesc();
1099	    GE_CHECK_NOTNULL(op_desc->MutableOutputDesc(0));
1100	    tensor_attr_group = op_desc->MutableOutputDesc(0)->GetOrCreateAttrsGroup<af::AscTensorAttr>();
1101	    GE_ASSERT_NOTNULL(tensor_attr_group);
1102	    tensor_attr_group->dtype = reduce_input_attr.dtype;
1103	  }
1104	  {
1105	    // 设置workspace_post_index和load_index的输出dtype为DT_INT64
1106	    auto op_desc = index_nodes.index_workspace_post_node->GetOpDesc();
1107	    GE_CHECK_NOTNULL(op_desc->MutableOutputDesc(0));
1108	    auto tensor_attr_group = op_desc->MutableOutputDesc(0)->GetOrCreateAttrsGroup<af::AscTensorAttr>();
1109	    GE_ASSERT_NOTNULL(tensor_attr_group);
1110	    tensor_attr_group->dtype = ge::DT_INT64;
1111	
1112	    op_desc = index_nodes.index_load_node->GetOpDesc();
1113	    GE_CHECK_NOTNULL(op_desc->MutableOutputDesc(0));
1114	    tensor_attr_group = op_desc->MutableOutputDesc(0)->GetOrCreateAttrsGroup<af::AscTensorAttr>();
1115	    GE_ASSERT_NOTNULL(tensor_attr_group);
1116	    tensor_attr_group->dtype = ge::DT_INT64;
1117	  }
1118	
1119	  return ge::GRAPH_SUCCESS;
1120	}
1121	
1122	// 连接ArgMax Phase2的所有边
1123	// 参数：1.输出锚点 2.输出边 3.Phase2节点集合 4.index workspace节点 5.index load节点
1124	static Status ConnectArgMaxPhase2Edges(af::OutDataAnchorPtr argmax_out_anchor,
1125	                                       const std::vector<af::InDataAnchorPtr> &argmax_out_edges,
1126	                                       const ReducePhase2Nodes &phase2_nodes,
1127	                                       const af::AscNodePtr &index_workspace_post_node,
1128	                                       const af::AscNodePtr &index_load_node) {
1129	  // 重定向原始ArgMax的输出边到new_reduce_node（ArgMaxMultiRPhase2）
1130	  for (const auto &peer_in_anchor : argmax_out_edges) {
1131	    // 移除原始边（虽然reduce_node已被删除，但移除边的操作应该还能执行）
1132	    GE_CHK_STATUS_RET(af::GraphUtils::RemoveEdge(argmax_out_anchor, peer_in_anchor));
1133	    // 添加新边：从new_reduce_node的输出0到下游节点
1134	    // ArgMaxMultiRPhase2只有1个输出（最终的index），所以输出索引是0
1135	    GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(phase2_nodes.new_reduce_node->GetOutAnchor(0UL), peer_in_anchor));
1136	  }
1137	
1138	  // 连接Phase2的所有边
1139	  // Phase2 value路径：workspace_post -> load -> new_reduce[输入0]
1140	  GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(phase2_nodes.workspace_post_node->GetOutAnchor(0UL),
1141	                                            phase2_nodes.load_node->GetInAnchor(0UL)));
1142	  GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(phase2_nodes.load_node->GetOutAnchor(0UL),
1143	                                            phase2_nodes.new_reduce_node->GetInAnchor(0UL)));
1144	
1145	  // Phase2 index路径：workspace_post_index -> index_load -> new_reduce[输入1]
1146	  GE_CHK_STATUS_RET(
1147	      af::GraphUtils::AddEdge(index_workspace_post_node->GetOutAnchor(0UL), index_load_node->GetInAnchor(0UL)));
1148	  GE_CHK_STATUS_RET(
1149	      af::GraphUtils::AddEdge(index_load_node->GetOutAnchor(0UL), phase2_nodes.new_reduce_node->GetInAnchor(1UL)));
1150	
1151	  return ge::GRAPH_SUCCESS;
1152	}
1153	
1154	// 处理ArgMax在R轴分核时的完整逻辑
1155	// 包括：创建index路径节点、替换为Phase1算子、设置属性、连接边等
1156	static Status HandleArgMaxPartition(const af::AscNodePtr &reduce_node, ReducePhase1Nodes &phase1_nodes,
1157	                                    ReducePhase2Nodes &phase2_nodes, const ArgMaxPartitionGraphContext &ctx) {
1158	  // ArgMax特殊处理：需要额外的workspace用于index
1159	  af::ascir_op::Workspace index_workspace_pre((ctx.graph_name + "_workspace_index").c_str());
1160	  af::ascir_op::Workspace index_workspace_post((ctx.graph_name + "_workspace_index").c_str());
1161	
1162	  // 为index路径创建额外的workspace和load节点
1163	  af::AscNodePtr index_workspace_pre_node = ctx.impl_graph.AddNode(index_workspace_pre);
1164	  af::AscNodePtr index_workspace_post_node = ctx.impl_graph.AddNode(index_workspace_post);
1165	  ctx.node_order.emplace_back(index_workspace_pre_node);
1166	
1167	  af::ascir_op::Load index_load((ctx.graph_name + "_load_index").c_str());
1168	  af::AscNodePtr index_load_node = ctx.impl_graph.AddNode(index_load);
1169	  // 参考load_node的处理方式，不复制属性（避免从Phase1节点复制错误的sched.axis）
1170	
1171	  const auto &saved_reduce_input_attr = reduce_node->inputs[0].attr;
1172	  const auto &saved_reduce_output_attr = reduce_node->outputs[0].attr;
1173	
1174	  // 保存ArgMax的输出边，用于后续重定向到new_reduce_node
1175	  af::OutDataAnchorPtr argmax_out_anchor = reduce_node->GetOutDataAnchor(0UL);
1176	  std::vector<af::InDataAnchorPtr> argmax_out_edges;
1177	  if (argmax_out_anchor != nullptr) {
1178	    for (const auto &peer_in_anchor : argmax_out_anchor->GetPeerInDataAnchors()) {
1179	      GE_ASSERT_NOTNULL(peer_in_anchor);
1180	      argmax_out_edges.push_back(peer_in_anchor);
1181	    }
1182	  }
1183	
1184	  // 复制节点级别的属性（sched、ir_attr等）
1185	  // 在调用ReplaceArgMaxInPhase1之前保存，因为调用后reduce_node将被删除
1186	  auto src_asc_node_attr = reduce_node->GetOpDesc()->GetOrCreateAttrsGroup<af::AscNodeAttr>();
1187	  af::AscNodeAttr saved_node_attr;
1188	  if (src_asc_node_attr != nullptr) {
1189	    saved_node_attr = *src_asc_node_attr;
1190	  }
1191	
1192	  // 在阶段1替换为ArgMaxMultiRPhase1，并处理额外的index输出
1193	  GE_CHK_STATUS_RET(ReplaceArgMaxInPhase1(ctx.impl_graph, reduce_node, phase1_nodes.store_node,
1194	                                          phase1_nodes.workspace_pre_node, index_workspace_pre_node));
1195	
1196	  // 设置ArgMax Phase2的所有属性
1197	  ReduceSavedNodeAttrInfo saved_attr_info = {src_asc_node_attr, saved_node_attr};
1198	  ArgMaxIndexNodes index_nodes = {index_workspace_post_node, index_load_node};
1199	  GE_CHK_STATUS_RET(SetupArgMaxPhase2Attrs(saved_attr_info, phase2_nodes, saved_reduce_input_attr,
1200	                                           saved_reduce_output_attr, index_nodes));
1201	
1202	  // 复制Phase2的workspace属性，与Phase1的workspace通过相同名称关联到同一buffer
1203	  // 注意：在设置dtype之后调用，避免覆盖正确的dtype
1204	  GE_ASSERT_GRAPH_SUCCESS(DoCopyWorkspaceTensorAttr(phase2_nodes.load_node, phase2_nodes.workspace_post_node));
1205	  GE_ASSERT_GRAPH_SUCCESS(DoCopyWorkspaceTensorAttr(index_load_node, index_workspace_post_node));
1206	
1207	  // 连接ArgMax Phase2的所有边
1208	  GE_CHK_STATUS_RET(ConnectArgMaxPhase2Edges(argmax_out_anchor, argmax_out_edges, phase2_nodes,
1209	                                             index_workspace_post_node, index_load_node));
1210	
1211	  return ge::GRAPH_SUCCESS;
1212	}
1213	
1214	// R轴分核时，为ArgMax创建额外的workspace和load节点用于index
1215	Status RMulticorePhase2Graph::PartitionByReduce(ascir::ImplGraph &impl_graph, ReduceType &phase2graph_reduce,
1216	                                                std::vector<af::AscNodePtr> &node_order) {
1217	  af::ascir_op::Workspace workspace_pre((phase2graph.GetName() + "_workspace").c_str());
1218	  af::ascir_op::Workspace workspace_post((phase2graph.GetName() + "_workspace").c_str());
1219	  af::ascir_op::Load load((phase2graph.GetName() + "_load").c_str());
1220	  af::ascir_op::Store store((phase1graph.GetName() + "Store").c_str());
1221	
1222	  af::AscNodePtr new_reduce_node;
1223	  std::visit([&new_reduce_node, &impl_graph](auto &&reduce_op) { new_reduce_node = impl_graph.AddNode(reduce_op); },
1224	             phase2graph_reduce);
1225	
1226	  auto workspace_pre_node = impl_graph.AddNode(workspace_pre);
1227	  node_order.emplace_back(workspace_pre_node);
1228	  auto workspace_post_node = impl_graph.AddNode(workspace_post);
1229	  auto load_node = impl_graph.AddNode(load);
1230	  GE_ASSERT_NOTNULL(load_node);
1231	  auto store_node = impl_graph.AddNode(store);
1232	  GE_ASSERT_NOTNULL(store_node);
1233	
1234	  if (reduce_node->GetType() == "ArgMax") {
1235	    // ArgMax特殊处理：调用专用函数处理双路径（value和index）逻辑
1236	    ReducePhase1Nodes phase1_nodes = {store_node, workspace_pre_node};
1237	    ReducePhase2Nodes phase2_nodes = {workspace_post_node, load_node, new_reduce_node};
1238	    ArgMaxPartitionGraphContext ctx = {impl_graph, node_order, phase2graph.GetName()};
1239	    GE_CHK_STATUS_RET(HandleArgMaxPartition(reduce_node, phase1_nodes, phase2_nodes, ctx));
1240	  } else {
1241	    // 普通reduce算子的处理逻辑
1242	    GE_ASSERT_GRAPH_SUCCESS(DoCopyAscNodeTensorAttr(reduce_node, new_reduce_node));
1243	    GE_ASSERT_GRAPH_SUCCESS(DoCopyAscNodeTensorAttr(reduce_node, store_node));
1244	    GE_ASSERT_GRAPH_SUCCESS(DoCopyWorkspaceTensorAttr(reduce_node, workspace_pre_node));
1245	    GE_ASSERT_GRAPH_SUCCESS(DoCopyWorkspaceTensorAttr(load_node, workspace_post_node));
1246	    for (const auto &reduce_out_anchor : reduce_node->GetAllOutDataAnchors()) {
1247	      GE_ASSERT_NOTNULL(reduce_out_anchor);
1248	      for (const auto &peer_in_anchor : reduce_out_anchor->GetPeerInDataAnchors()) {
1249	        GE_ASSERT_NOTNULL(peer_in_anchor);
1250	        auto reduce_out_node = peer_in_anchor->GetOwnerNode();
1251	        GE_ASSERT_NOTNULL(reduce_out_node);
1252	        GE_CHK_STATUS_RET(af::GraphUtils::RemoveEdge(reduce_node->GetOutAnchor(reduce_out_anchor->GetIdx()),
1253	                                                     reduce_out_node->GetInAnchor(peer_in_anchor->GetIdx())));
1254	        GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(new_reduce_node->GetOutAnchor(reduce_out_anchor->GetIdx()),
1255	                                                  reduce_out_node->GetInAnchor(peer_in_anchor->GetIdx())));
1256	      }
1257	    }
1258	    // add reduce->store->workspace_pre_node
1259	    GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(reduce_node->GetOutAnchor(0UL), store_node->GetInAnchor(0UL)));
1260	    GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(store_node->GetOutAnchor(0UL), workspace_pre_node->GetInAnchor(0UL)));
1261	    // add workspace_post_node->load->new reduce
1262	    GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(workspace_post_node->GetOutAnchor(0UL), load_node->GetInAnchor(0UL)));
1263	    GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(load_node->GetOutAnchor(0UL), new_reduce_node->GetInAnchor(0UL)));
1264	  }
1265	
1266	  return ge::GRAPH_SUCCESS;
1267	}
1268	
1269	Status RMulticorePhase2Graph::SetNodeOrder(std::vector<af::AscNodePtr> &node_order) {
1270	  auto new_reduce_node =
1271	      phase_graph.FindNode((phase2graph.GetName() + "_" + reduce_node->GetName() + "_reduce").c_str());
1272	  GE_ASSERT_NOTNULL(new_reduce_node);
1273	  std::set<af::NodePtr> visited{new_reduce_node};
1274	  std::list<af::NodePtr> next_nodes{new_reduce_node};
1275	  while (!next_nodes.empty()) {
1276	    const auto node = next_nodes.front();
1277	    GE_ASSERT_NOTNULL(node);
1278	    next_nodes.pop_front();
1279	    if (node->GetOutDataNodes().empty()) {
1280	      node_order.emplace_back(std::dynamic_pointer_cast<af::AscNode>(node));
1281	    }
1282	    for (auto &out_node : node->GetOutDataNodes()) {
1283	      if (visited.find(out_node) == visited.cend()) {
1284	        next_nodes.emplace_back(out_node);
1285	        visited.emplace(out_node);
1286	      }
1287	    }
1288	  }
1289	  return af::SUCCESS;
1290	}
1291	}  // namespace optimize
