32	constexpr uint32_t kMaxInputNum = 48U;
33	constexpr size_t kTemplateSizeAll = 3UL;
34	constexpr int32_t kConcatAlgTranspose = 0;
35	constexpr int64_t kSmallDimSizeThreshold = 256;
