37	void CollectInAndOutNodes(const af::NodePtr &node, std::set<af::Node *> &visited_nodes,
38	                          std::queue<af::NodePtr> &nodes) {
39	  for (const auto &in_node : node->GetInDataNodes()) {
40	    if (visited_nodes.emplace(in_node.get()).second) {
41	      nodes.emplace(in_node);
42	    }
43	  }
44	  for (const auto &out_node : node->GetOutDataNodes()) {
45	    if (visited_nodes.emplace(out_node.get()).second) {
46	      nodes.emplace(out_node);
47	    }
48	  }
49	}
50	
51	void ReplaceAxisById(std::vector<ascir::AxisId> &axes, ascir::AxisId old_id, ascir::AxisId new_id) {
52	  for (auto &axis_id : axes) {
53	    if (axis_id == old_id) {
54	      axis_id = new_id;
55	    }
56	  }
57	}
58	}  // namespace
59	
60	Status ConcatFusionCaseGenerator::AddTemplatesForFirstDimConcat(const af::AscNodePtr &concat_node,
61	                                                                ascir::HintGraph &graph,
62	                                                                std::vector<ascir::ImplGraph> &graphs) {
63	  const bool is_one_axis = (concat_node->outputs[0].attr.repeats.size() == 1UL);
64	  const bool is_single_input = concat_node->inputs.Size() == 1U;
65	  if ((!is_single_input) && (!convert_to_store_) && (!support_small_tail_) && (is_one_axis || (concat_dim_ > 0))) {
66	    // 单维concat, 在前面补轴，复用非首轴处理逻辑
67	    // 先限制单维，后续处理多维但小包场景
68	    if (is_one_axis) {
69	      GE_ASSERT_SUCCESS(InsertAxis(graph), "Failed to insert axis for graph:[%s].", graph.GetName().c_str());
70	      concat_dim_ = 1;
71	      GE_ASSERT_SUCCESS(AddTemplateIfCanFitInOneKernel(concat_node, graph, graphs));
72	    }
73	    GE_ASSERT_SUCCESS(AddTemplateForSplitConcat(graph, graphs));
74	    GE_ASSERT_SUCCESS(MarkNoMergeFirstAxis(graphs));
75	    return af::SUCCESS;
76	  }
77	  // gm concat
78	  GE_CHK_STATUS_RET(Prepare(concat_node, concat_dim_), "Prepare failed");
79	  GE_CHK_STATUS_RET(ConvertConcatToStores(graph, concat_node), "ConvertConcatToStores failed");
80	  graphs.emplace_back(graph);
81	  GELOGI("concat on first dim, num_inputs = %u, 1 template was generated", concat_node->inputs.Size());
82	  return af::SUCCESS;
83	}
84	
85	Status ConcatFusionCaseGenerator::Generate(ascir::HintGraph &graph, std::vector<ascir::ImplGraph> &graphs,
86	                                           std::vector<std::string> &score_functions) {
87	  bool has_unsupported_op = false;
88	  const auto concat_nodes = FindConcatNodes(graph, &has_unsupported_op);
89	  if (concat_nodes.empty()) {
90	    return af::SUCCESS;
91	  }
92	  auto &concat_node = concat_nodes.front();
93	  bool is_first_dim = false;
94	  GE_CHK_STATUS_RET(ScheduleUtils::ResolveDiffDim(concat_node, concat_dim_, is_first_dim), "ResolveConcatDim failed");
95	  GE_ASSERT_SUCCESS(AddExtraShapeEnv(concat_node, concat_dim_));
96	  GE_ASSERT_SUCCESS(SplitDataForDifferentConcatDim(graph), "Failed to split data for graph:[%s].",
97	                    graph.GetName().c_str());
98	  if (has_unsupported_op) {
99	    GE_CHK_STATUS_RET(Prepare(concat_node, concat_dim_), "Prepare failed");
100	    GE_CHK_STATUS_RET(ConvertConcatToStores(graph, concat_node), "ConvertConcatToStores failed");
101	    return af::SUCCESS;
102	  }
103	
104	  const auto backend_spec = BackendSpec::GetInstance();
105	  GE_ASSERT_NOTNULL(backend_spec);
106	  support_small_tail_ = backend_spec->concat_alg == kConcatAlgTranspose;
107	  // case1. 首轴concat，转store
108	  if (is_first_dim) {
109	    return AddTemplatesForFirstDimConcat(concat_node, graph, graphs);
110	  }
111	
112	  // case2. 生成ub内concat的case
113	  if ((concat_node->inputs.Size() <= kMaxInputNum)) {
114	    graphs.emplace_back(graph);
115	    // 如果匹配小尾轴, UB能全载，则不需要生成case3模板
116	    if (support_small_tail_ && ascir::utils::UseSmallTailConcatApi(*concat_node)) {
117	      GELOGI("match small tail pattern, 1 template was generated");
118	      return af::SUCCESS;
119	    }
120	  }
121	
122	  // case3. 在ub不全载的case的图中, 对concat进行分组
123	  GE_ASSERT_SUCCESS(AddTemplateForSplitConcat(graph, graphs));
124	
125	  // 如果是动态shape, 添加small tail模板，运行时通过score func选择
126	  if (NeedDynSmallTailTemplate(concat_node)) {
127	    GE_ASSERT_SUCCESS(AddTemplateForSmallTail(graph, graphs));
128	  }
129	
130	  GE_ASSERT_SUCCESS(RunCastOptimizationPass(graphs));
131	  if (!support_small_tail_) {
132	    GE_ASSERT_SUCCESS(ConcatInputUnificationPass::Run(graphs));
133	  }
134	
135	  // 多模板, 为ub concat模板提供打分函数
136	  GE_ASSERT_SUCCESS(GenerateScoreFunctions(graphs, concat_dim_, score_functions));
137	  return af::SUCCESS;
138	}
139	
140	ConcatFusionCaseGenerator &ConcatFusionCaseGenerator::SetConvertToStoreMode() {
141	  convert_to_store_ = true;
142	  return *this;
143	}
144	
145	Status ConcatFusionCaseGenerator::AddTemplateForSplitConcat(const ascir::HintGraph &graph,
146	                                                            std::vector<ascir::ImplGraph> &graphs) {
147	  ascir::ImplGraph optimized_graph((graph.GetName() + "_group_concat").c_str());
148	  GE_ASSERT_TRUE(optimized_graph.CopyFrom(graph));
149	  auto concat_node = FindConcatNodes(optimized_graph).front();
150	  GE_CHK_STATUS_RET(Prepare(concat_node, concat_dim_), "Prepare failed");
151	  split_concat_ = false;
152	  GE_CHK_STATUS_RET(SplitConcats(optimized_graph, concat_node, split_concat_), "SplitConcats failed");
153	  GELOGI("Concat on non-first dim, split concat into groups templates generated, split = %d",
154	         static_cast<int32_t>(split_concat_));
155	  if (split_concat_) {
156	    if (concat_node->outputs[0].attr.repeats[concat_dim_].IsConstExpr() && (!KeepOriginGraph(concat_node))) {
157	      // 经过split的性能更好, 防止ATT选错, 删除非Split的
158	      graphs.clear();
159	    }
160	  } else {
161	    GE_CHK_STATUS_RET(ConvertConcatToStores(optimized_graph, concat_node), "ConvertConcatToStores failed");
162	  }
163	  graphs.emplace_back(optimized_graph);
164	  return af::SUCCESS;
165	}
166	
167	bool ConcatFusionCaseGenerator::NeedDynSmallTailTemplate(const af::AscNodePtr &concat_node) const {
168	  const auto dtype_size = GetSizeByDataType(concat_node->outputs[0].attr.dtype);
169	  GE_WARN_ASSERT(dtype_size > 0);
170	  return support_small_tail_ && ((dtype_size == sizeof(uint16_t)) || (dtype_size == sizeof(uint32_t))) &&
171	         (concat_node->inputs.Size() <= kMaxInputNum) &&
172	         (!concat_node->outputs[0].attr.strides[concat_dim_ - 1].IsConstExpr());
173	}
174	
175	Status ConcatFusionCaseGenerator::AddTemplateForSmallTail(const ascir::HintGraph &graph,
176	                                                          std::vector<ascir::ImplGraph> &graphs) {
177	  GELOGI("exists dynamic dim after concat_dim, generate force small tail template");
178	  ascir::ImplGraph force_small_tail_graph((graph.GetName() + "_force_small_tail").c_str());
179	  GE_ASSERT_TRUE(force_small_tail_graph.CopyFrom(graph));
180	  auto force_small_tail_node = FindConcatNodes(force_small_tail_graph).front();
181	  GE_ASSERT_TRUE(af::AttrUtils::SetBool(force_small_tail_node->GetOpDesc(), "_concat_small_tail", true));
182	  graphs.emplace_back(force_small_tail_graph);
183	  return af::SUCCESS;
184	}
185	
186	Status ConcatFusionCaseGenerator::GenerateScoreFunctions(const std::vector<ascir::ImplGraph> &graphs, size_t concat_dim,
187	                                                         std::vector<std::string> &score_functions) const {
188	  GE_CHK_BOOL_RET_STATUS_NOLOG((graphs.size() > 1U), af::SUCCESS);
189	  if (support_small_tail_) {
190	    if (!has_recompute_) {
191	      score_functions.resize(graphs.size());
192	      const auto concat_node = FindConcatNodes(graphs.front()).front();
193	      GE_CHK_STATUS_RET(
194	          ConcatScoreFunctionGenerator(graphs.front(), concat_node, concat_dim).Generate(score_functions.front()),
195	          "Failed to generate score func for ub_concat");
196	      if (graphs.size() == kTemplateSizeAll) {
197	        GE_CHK_STATUS_RET(ConcatScoreFunctionGenerator(graphs.back(), concat_node, concat_dim)
198	                              .GenerateForCheckSmallTail(score_functions.back()),
199	                          "Failed to generate score func for small_tail_concat");
200	      }
201	    }
202	  } else {
203	    // 没有分组时, 优先UB全载的模板
204	    if (!split_concat_) {
205	      const auto concat_node = FindConcatNodes(graphs.front()).front();
206	      constexpr uint32_t kMaxNumInputs = 16;
207	      if ((!has_recompute_) && (concat_node->inputs.Size() <= kMaxNumInputs) &&
208	          IsSmallBlock(concat_node, concat_dim_)) {
209	        score_functions.resize(graphs.size());
210	        ConcatScoreFunctionGenerator::GenerateScoreOne(score_functions.front());
211	      }
212	    }
213	  }
214	  return af::SUCCESS;
215	}
216	
217	std::vector<af::AscNodePtr> ConcatFusionCaseGenerator::FindConcatNodes(const ascir::HintGraph &owner_graph,
218	                                                                       bool *has_unsupported_op) {
219	  if (has_unsupported_op != nullptr) {
220	    *has_unsupported_op = false;
221	  }
222	  std::vector<af::AscNodePtr> concat_nodes;
223	  for (const auto &node : owner_graph.GetAllNodes()) {
224	    if (af::ops::IsOps<af::ascir_op::Concat>(node)) {
225	      concat_nodes.emplace_back(node);
226	    } else if (has_unsupported_op != nullptr && (!*has_unsupported_op)) {
227	      const auto asc_node = std::dynamic_pointer_cast<af::AscNode>(node);
228	      if ((asc_node != nullptr) && (ScheduleUtils::IsTranspose(asc_node) || ScheduleUtils::IsReduce(asc_node))) {
229	        *has_unsupported_op = true;
230	        GELOGI("graph contains Transpose/Reduce node %s", node->GetNamePtr());
231	      }
232	    } else {
233	      // do nothing
234	    }
235	  }
236	  return concat_nodes;
237	}
238	
239	Status ConcatFusionCaseGenerator::ConvertSingleInput(ascir::HintGraph &owner_graph, const af::AscNodePtr &concat_node,
240	                                                     size_t in_index, size_t group_idx,
241	                                                     ConcatDimAxisMap &repeat_to_axis_id) {
242	  const auto &all_in_data_anchors = concat_node->GetAllInDataAnchors();
243	  const auto &loop_axis = owner_graph.GetAllAxis();
244	
245	  const auto &concat_in_anchor = all_in_data_anchors.at(in_index);
246	  auto input_repeat = concat_node->inputs[in_index].attr.repeats[concat_dim_];
247	
248	  if (repeat_to_axis_id.find(input_repeat) == repeat_to_axis_id.end()) {
249	    auto new_axis =
250	        owner_graph.CreateAxis(loop_axis[concat_dim_]->name + "_" + std::to_string(group_idx), input_repeat);
251	    repeat_to_axis_id[input_repeat] = new_axis.id;
252	    GELOGD("Create axis [%s, %ld] for input repeat=[%s].", new_axis.name.c_str(), new_axis.id,
253	           af::SymbolicUtils::ToString(input_repeat).c_str());
254	  }
255	  auto replace_axis = owner_graph.FindAxis(repeat_to_axis_id[input_repeat]);
256	  GE_ASSERT_NOTNULL(replace_axis);
257	
258	  return ReplaceWithStore(concat_node, concat_in_anchor, *replace_axis);
259	}
