261	Status ConcatFusionCaseGenerator::ConvertConcatToStores(ascir::HintGraph &owner_graph,
262	                                                        const af::AscNodePtr &concat_node) {
263	  ConcatGroupPartitioner partitioner(concat_node, concat_dim_);
264	  GE_ASSERT_SUCCESS(partitioner.RecomputeDiffAxes());
265	  has_recompute_ = partitioner.HasRecompute();
266	  GE_ASSERT_SUCCESS(PrepareForModifyingGraph(concat_node));
267	  ConcatDimAxisMap repeat_to_axis_id;
268	  const auto all_in_data_anchors_count = concat_node->GetAllInDataAnchors().size();  // 只需获取一次大小
269	  for (size_t i = 0UL; i < all_in_data_anchors_count; ++i) {
270	    const auto in_index = all_in_data_anchors_count - i - 1UL;
271	    GE_ASSERT_SUCCESS(ConvertSingleInput(owner_graph, concat_node, in_index, i, repeat_to_axis_id),
272	                      "ProcessSingleInput failed in ConvertConcatToStores");
273	  }
274	
275	  GE_CHK_STATUS_RET(RemoveUnusedNodes(concat_node, post_concat_nodes_), "RemoveUnusedNodes failed");
276	  GE_CHK_STATUS_RET(PassUtils::PruneGraph(owner_graph), "Prune graph failed");
277	  GE_ASSERT_GRAPH_SUCCESS(ScheduleUtils::TopologicalSorting(owner_graph));
278	  ascir::utils::DumpGraph(owner_graph, "AfterConvertConcatToStore");
279	  return af::SUCCESS;
280	}
