282	Status ConcatFusionCaseGenerator::SplitConcats(ascir::HintGraph &owner_graph, const af::AscNodePtr &concat_node,
283	                                               bool &split) {
284	  std::vector<ConcatGroupPartitioner::ConcatGroup> groups;
285	  ConcatGroupPartitioner partitioner(concat_node, concat_dim_);
286	  GE_ASSERT_SUCCESS(partitioner.PartitionGroups(groups));
287	  if ((groups.size() <= 1U) || (groups.size() == concat_node->inputs.Size())) {
288	    return af::SUCCESS;
289	  }
290	  has_recompute_ = partitioner.HasRecompute();
291	  GE_ASSERT_SUCCESS(PrepareForModifyingGraph(concat_node));
292	  for (size_t i = 0U; i < groups.size(); ++i) {
293	    const auto &group = groups[i];
294	    GELOGI("group[%zu] start = %ld, end = %ld", i, group.start, group.end);
295	  }
296	  ConcatDimAxisMap repeat_to_axis_id;
297	  auto loop_axis = owner_graph.GetAllAxis();
298	  for (size_t i = 0U; i < groups.size(); ++i) {
299	    const auto &group = groups[groups.size() - i - 1];
300	    if (group.end - group.start == 1) {
301	      GE_ASSERT_SUCCESS(ConvertSingleInput(owner_graph, concat_node, group.start, i, repeat_to_axis_id),
302	                        "ProcessSingleInput failed in ConvertConcatToStores");
303	    } else {
304	      // loads -> concat -> store
305	      GE_CHK_STATUS_RET(ReplaceWithConcat(owner_graph, concat_node, group.start, group.end));
306	    }
307	  }
308	  GE_CHK_STATUS_RET(RemoveUnusedNodes(concat_node, post_concat_nodes_), "RemoveUnusedNodes failed");
309	  GE_CHK_STATUS_RET(PassUtils::PruneGraph(owner_graph), "Prune graph failed");
310	  GE_ASSERT_GRAPH_SUCCESS(ScheduleUtils::TopologicalSorting(owner_graph));
311	  ascir::utils::DumpGraph(owner_graph, "AfterSplitConcat");
312	  split = true;
313	  return af::SUCCESS;
314	}
