316	Status ConcatFusionCaseGenerator::Prepare(const af::AscNodePtr &concat_node, size_t concat_dim) {
317	  af::Expression dim_offset = af::ops::Zero;
318	  for (const auto &in_anchor : concat_node->GetAllInDataAnchorsPtr()) {
319	    GE_ASSERT_NOTNULL(in_anchor);
320	    concat_dim_offsets_.emplace_back(dim_offset);
321	    dim_offset = dim_offset + concat_node->inputs[static_cast<uint32_t>(in_anchor->GetIdx())].attr.repeats[concat_dim];
322	  }
323	  concat_axis_id_ = concat_node->attr.sched.axis[concat_dim];
324	  return af::SUCCESS;
325	}
