327	Status ConcatFusionCaseGenerator::PropagateAxisChanges(af::Node *start_node, ascir::AxisId old_axis_id,
328	                                                       ascir::AxisId new_axis_id) {
329	  std::set<af::Node *> visited_nodes;
330	  std::queue<af::Node *> node_queue;
331	
332	  visited_nodes.emplace(start_node);
333	  node_queue.emplace(start_node);
334	
335	  while (!node_queue.empty()) {
336	    const auto curr_node = dynamic_cast<af::AscNode *>(node_queue.front());
337	    node_queue.pop();
338	    GE_ASSERT_NOTNULL(curr_node);
339	    if (curr_node->attr.api.type != af::ApiType::kAPITypeBuffer) {
340	      ReplaceAxisById(curr_node->attr.sched.axis, old_axis_id, new_axis_id);
341	      for (const auto &out_tensor : curr_node->outputs()) {
342	        ReplaceAxisById(out_tensor->attr.axis, old_axis_id, new_axis_id);
343	      }
344	    }
345	
346	    for (const auto &out_node : curr_node->GetOutDataNodes()) {
347	      if (visited_nodes.count(out_node.get()) == 0UL) {
348	        visited_nodes.emplace(out_node.get());
349	        node_queue.emplace(out_node.get());
350	      }
351	    }
352	
353	    for (const auto &in_node : curr_node->GetInDataNodes()) {
354	      if (visited_nodes.count(in_node.get()) == 0UL) {
355	        visited_nodes.emplace(in_node.get());
356	        node_queue.emplace(in_node.get());
357	      }
358	    }
359	  }
360	  return af::SUCCESS;
361	}
