363	Status ConcatFusionCaseGenerator::ReplaceWithStore(const af::AscNodePtr &concat_node,
364	                                                   const af::InDataAnchorPtr &concat_in_anchor,
365	                                                   const af::Axis &replace_axis) {
366	  const auto in_index = concat_in_anchor->GetIdx();
367	  const auto &src_out_anchor = concat_in_anchor->GetPeerOutAnchor();
368	  const auto old_axis_id = concat_node->attr.sched.axis[concat_dim_];
369	  const auto new_axis_id = replace_axis.id;
370	  // 前向刷轴
371	  GE_CHK_STATUS_RET(PropagateAxisChanges(concat_node.get(), old_axis_id, new_axis_id),
372	                    "PropagateAxisChanges failed in ReplaceWithStore");
373	  GE_ASSERT_NOTNULL(src_out_anchor);
374	  concat_in_anchor->UnlinkAll();
375	  std::vector<af::InDataAnchorPtr> dst_in_anchors;
376	  auto src_node = dynamic_cast<af::AscNode *>(src_out_anchor->GetOwnerNodeBarePtr());
377	  GE_ASSERT_NOTNULL(src_node);
378	  std::unordered_map<std::string, af::NodePtr> name_to_new_node;
379	  GE_ASSERT_SUCCESS(CloneNonConcatNodes(replace_axis, old_axis_id, in_index, dst_in_anchors, name_to_new_node));
380	  for (const auto &peer_in_anchor : dst_in_anchors) {
381	    GE_ASSERT_GRAPH_SUCCESS(af::GraphUtils::AddEdge(src_out_anchor, peer_in_anchor));
382	    GE_ASSERT_SUCCESS(ReconnectIfShareSameAncestor(name_to_new_node, peer_in_anchor));
383	  }
384	  return af::SUCCESS;
385	}
