387	Status ConcatFusionCaseGenerator::ReplaceWithConcat(ascir::ImplGraph &owner_graph, const af::AscNodePtr &concat_node,
388	                                                    size_t start, size_t end) {
389	  auto suffix = "_" + std::to_string(start) + "_" + std::to_string(end);
390	  af::ascir_op::Concat concat_op((concat_node->GetName() + suffix).c_str());
391	  SetConcatOpAttr(concat_op, concat_node, concat_dim_, start, end);
392	  auto new_concat_node = owner_graph.AddNode(concat_op);
393	  GE_ASSERT_NOTNULL(new_concat_node);
394	  GELOGD("split concat [%zu, %zu), output repeats = %s", start, end,
395	         af::ToString(new_concat_node->outputs[0].attr.repeats).c_str());
396	  for (size_t i = end; i > start; --i) {
397	    auto concat_in_anchor = concat_node->GetInDataAnchor(static_cast<int32_t>(i) - 1);
398	    GE_CHECK_NOTNULL(concat_in_anchor);
399	    auto peer_out_anchor = concat_in_anchor->GetPeerOutAnchor();
400	    GE_CHECK_NOTNULL(peer_out_anchor);
401	    GE_CHK_STATUS_RET(af::GraphUtils::RemoveEdge(peer_out_anchor, concat_in_anchor), "Failed to RemoveEdge");
402	    GE_CHK_STATUS_RET(af::GraphUtils::AddEdge(peer_out_anchor, new_concat_node->GetInDataAnchor(i - start - 1)),
403	                      "Failed to AddEdge");
404	  }
405	  const auto &output_repeats = new_concat_node->outputs[0].attr.repeats;
406	  ascir::Axis concat_axis = *(owner_graph.GetAllAxis().at(concat_axis_id_));
407	  auto new_concat_axis =
408	      owner_graph.CreateAxis(concat_axis.name + "_ss_" + std::to_string(start), output_repeats[concat_dim_]);
409	
410	  // 前向刷轴
411	  const auto old_axis_id = concat_node->attr.sched.axis[concat_dim_];
412	  const auto new_axis_id = new_concat_axis.id;
413	  GE_CHK_STATUS_RET(PropagateAxisChanges(concat_node.get(), old_axis_id, new_axis_id),
414	                    "PropagateAxisChanges failed in ReplaceWithStore");
415	  GELOGD("New axis %s, size = %s", new_concat_axis.name.c_str(),
416	         af::SymbolicUtils::ToString(new_concat_axis.size).c_str());
417	  std::vector<af::InDataAnchorPtr> dst_in_anchors;
418	  GE_ASSERT_SUCCESS(ReplaceAxis(new_concat_node, old_axis_id, new_concat_axis));
419	  std::unordered_map<std::string, af::NodePtr> name_to_new_node;
420	  GE_ASSERT_SUCCESS(CloneNonConcatNodes(new_concat_axis, old_axis_id, start, dst_in_anchors, name_to_new_node));
421	  for (const auto &in_anchor : new_concat_node->GetAllInDataAnchors()) {
422	    GE_ASSERT_SUCCESS(ReconnectIfShareSameAncestor(name_to_new_node, in_anchor));
423	  }
424	  for (const auto &peer_in_anchor : dst_in_anchors) {
425	    GE_ASSERT_GRAPH_SUCCESS(af::GraphUtils::AddEdge(new_concat_node->GetOutDataAnchor(0), peer_in_anchor));
426	  }
427	  return af::SUCCESS;
428	}
429	
430	af::Status ConcatFusionCaseGenerator::SetConcatOpAttr(af::ascir_op::Concat &concat_op,
431	                                                      const af::AscNodePtr &concat_node, size_t concat_dim,
432	                                                      size_t start, size_t end) {
433	  GE_ASSERT_TRUE(end <= concat_node->inputs.Size());
434	  auto repeats = concat_node->inputs[start].attr.repeats;
435	  for (size_t i = start + 1U; i < end; ++i) {
436	    repeats[concat_dim] = repeats[concat_dim] + concat_node->inputs[i].attr.repeats[concat_dim];
437	  }
438	  af::Expression stride = af::sym::kSymbolOne;
439	  std::vector<af::Expression> strides(repeats.size(), af::sym::kSymbolOne);
440	  for (auto i = static_cast<int32_t>(repeats.size() - 1); i >= 0; --i) {
441	    strides[i] = stride;
442	    stride = (stride * repeats[i]);
443	  }
444	  const auto &concat_output_tensor_attr = concat_node->outputs[0].attr;
445	  concat_op.attr = concat_node->attr;
446	  concat_op.y.dtype = concat_output_tensor_attr.dtype;
447	  *concat_op.y.repeats = repeats;
448	  *concat_op.y.strides = strides;
449	  *concat_op.y.axis = concat_output_tensor_attr.axis;
450	  concat_op.DynamicInputRegister("x", end - start);
451	  return af::SUCCESS;
452	}
