466	Status ConcatFusionCaseGenerator::SplitDataForDifferentConcatDim(ascir::ImplGraph &owner_graph) {
467	  for (const auto &node : owner_graph.GetAllNodes()) {
468	    GE_ASSERT_NOTNULL(node);
469	    if (!ScheduleUtils::IsDataInput(node)) {
470	      continue;
471	    }
472	    auto output_anchor = node->GetOutDataAnchor(0);
473	    GE_ASSERT_NOTNULL(output_anchor);
474	    auto peer_in_anchors = output_anchor->GetPeerInDataAnchors();
475	    for (size_t idx = 1UL; idx < peer_in_anchors.size(); ++idx) {
476	      std::string node_name = node->GetName() + std::string("_") + std::to_string(idx);
477	      af::AscNodePtr data_node;
478	      if (af::ops::IsOps<af::ascir_op::ScalarData>(node)) {
479	        af::ascir_op::ScalarData scalar_data(node_name.c_str());
480	        data_node = owner_graph.AddNode(scalar_data);
481	      } else {
482	        af::ascir_op::Data data(node_name.c_str());
483	        data_node = owner_graph.AddNode(data);
484	      }
485	      GE_ASSERT_NOTNULL(data_node);
486	      data_node->attr = node->attr;
487	      data_node->outputs[0].attr = node->outputs[0].attr;
488	      auto new_out_anchor = data_node->GetOutDataAnchor(0);
489	      GE_ASSERT_NOTNULL(new_out_anchor);
490	      GE_ASSERT_SUCCESS(af::GraphUtils::RemoveEdge(output_anchor, peer_in_anchors.at(idx)));
491	      GE_ASSERT_SUCCESS(af::GraphUtils::AddEdge(new_out_anchor, peer_in_anchors.at(idx)));
492	    }
493	  }
494	  return af::SUCCESS;
495	}
