497	af::Status ConcatFusionCaseGenerator::CollectBackwardNodes(const af::NodePtr &concat_node,
498	                                                           std::vector<af::AscNodePtr> &nodes) {
499	  std::set<af::Node *> visited_nodes{concat_node.get()};
500	  std::queue<af::NodePtr> next_nodes;
501	  for (const auto &out_data_node : concat_node->GetOutDataNodes()) {
502	    if (visited_nodes.emplace(out_data_node.get()).second) {
503	      next_nodes.push(out_data_node);
504	    }
505	  }
506	  while (!next_nodes.empty()) {
507	    auto &top = next_nodes.front();
508	    auto asc_node = std::dynamic_pointer_cast<af::AscNode>(top);
509	    GE_ASSERT_NOTNULL(asc_node);
510	    nodes.emplace_back(asc_node);
511	    CollectInAndOutNodes(top, visited_nodes, next_nodes);
512	    next_nodes.pop();
513	  }
514	  std::sort(nodes.begin(), nodes.end(), [](const af::AscNodePtr &lhs, const af::AscNodePtr &rhs) -> bool {
515	    return lhs->GetOpDesc()->GetId() < rhs->GetOpDesc()->GetId();
516	  });
517	  return af::SUCCESS;
518	}
