520	Status ConcatFusionCaseGenerator::CollectReachableLoadNodes(const af::NodePtr &concat_node,
521	                                                            std::set<af::AscNodePtr> &nodes) {
522	  std::set<af::Node *> visited_nodes{concat_node.get()};
523	  std::queue<af::NodePtr> next_nodes;
524	  for (const auto &in_data_node : concat_node->GetInDataNodes()) {
525	    if (visited_nodes.emplace(in_data_node.get()).second) {
526	      next_nodes.push(in_data_node);
527	    }
528	  }
529	  while (!next_nodes.empty()) {
530	    auto &top = next_nodes.front();
531	    auto asc_node = std::dynamic_pointer_cast<af::AscNode>(top);
532	    GE_ASSERT_NOTNULL(asc_node);
533	    if (af::ops::IsOps<af::ascir_op::Load>(asc_node)) {
534	      nodes.emplace(asc_node);
535	    }
536	    CollectInAndOutNodes(top, visited_nodes, next_nodes);
537	    next_nodes.pop();
538	  }
539	  return af::SUCCESS;
540	}
