542	Status ConcatFusionCaseGenerator::CloneNonConcatNodes(const af::Axis &new_axis, ascir::AxisId old_axis_id, size_t index,
543	                                                      std::vector<af::InDataAnchorPtr> &in_anchors,
544	                                                      std::unordered_map<std::string, af::NodePtr> &name_to_new_node) {
545	  GE_ASSERT_TRUE(!post_concat_nodes_.empty());
546	  ascir::ImplGraph owner_graph("owner_graph");
547	  GE_ASSERT_SUCCESS(
548	      af::AscGraphUtils::FromComputeGraph(post_concat_nodes_.front()->GetOwnerComputeGraph(), owner_graph));
549	  std::string suffix;
550	  if (index != 0UL) {
551	    suffix = "_split_" + std::to_string(index);
552	  }
553	  std::unordered_map<std::string, af::NodePtr> all_new_nodes;
554	  for (const auto &asc_node : post_concat_nodes_) {
555	    const auto &op_desc = af::GraphUtils::CopyOpDesc(asc_node->GetOpDesc(), nullptr);
556	    GE_CHECK_NOTNULL(op_desc);
557	    op_desc->SetName(asc_node->GetName() + suffix);
558	    af::Operator op = af::OpDescUtils::CreateOperatorFromOpDesc(op_desc);
559	    auto dst_new_node = owner_graph.AddNode(op);
560	    all_new_nodes[dst_new_node->GetName()] = dst_new_node;
561	    name_to_new_node[asc_node->GetName()] = dst_new_node;
562	    GE_ASSERT_TRUE(af::AscGraph::CopyAscNodeTensorAttr(asc_node, dst_new_node),
563	                   "DoCopyAscNodeTensorAttr failed, node = %s[%s]", asc_node->GetNamePtr(), asc_node->GetTypePtr());
564	    if (dst_new_node->GetType() == af::ascir_op::Store::Type) {
565	      const auto offset = concat_dim_offsets_[index] * dst_new_node->outputs[0].attr.strides[concat_dim_];
566	      const auto ir_attr = dst_new_node->attr.ir_attr->DownCastTo<af::ascir_op::Store::AscStoreIrAttrDef>();
567	      GE_ASSERT_NOTNULL(ir_attr);
568	      GE_CHK_STATUS_RET(ir_attr->SetOffset(offset), "Failed to set offset to %s", dst_new_node->GetNamePtr());
569	      GELOGI("Store node: %s added, offset = %s", dst_new_node->GetName().c_str(), offset.Serialize().get());
570	    } else if ((dst_new_node->GetType() == af::ascir_op::Load::Type) &&
571	               (reachable_load_nodes_.find(asc_node) == reachable_load_nodes_.end())) {
572	      const auto offset = concat_dim_offsets_[index] * dst_new_node->outputs[0].attr.strides[concat_dim_];
573	      const auto ir_attr = dst_new_node->attr.ir_attr->DownCastTo<af::ascir_op::Load::AscLoadIrAttrDef>();
574	      GE_ASSERT_NOTNULL(ir_attr);
575	      GE_CHK_STATUS_RET(ir_attr->SetOffset(offset), "Failed to set offset to %s", dst_new_node->GetNamePtr());
576	      GELOGI("Load node: %s added, offset = %s", dst_new_node->GetName().c_str(), offset.Serialize().get());
577	    } else {
578	      // do nothing
579	    }
580	    if (const auto it = out_node_name_to_indices_.find(asc_node->GetName()); it != out_node_name_to_indices_.cend()) {
581	      for (const auto in_anchor_index : it->second) {
582	        in_anchors.emplace_back(dst_new_node->GetInDataAnchor(in_anchor_index));
583	      }
584	    }
585	    if (!ScheduleUtils::IsBuffer(dst_new_node)) {
586	      GE_ASSERT_SUCCESS(ReplaceAxis(dst_new_node, old_axis_id, new_axis));
587	    }
588	  }
589	  for (const auto &src_node : post_concat_nodes_) {
590	    GE_CHK_STATUS_RET(af::GraphUtils::RelinkGraphEdges(src_node, suffix, all_new_nodes), "RelinkGraphEdges failed");
591	  }
592	  return af::SUCCESS;
593	}
594	
595	af::Status ConcatFusionCaseGenerator::ReplaceAxis(const af::AscNodePtr &node, ascir::AxisId old_axis_id,
596	                                                  const af::Axis &to_axis) {
597	  for (int64_t &axis_id : node->attr.sched.axis) {
598	    if (axis_id == old_axis_id) {
599	      axis_id = to_axis.id;
600	    }
601	  }
602	
603	  for (uint32_t i = 0U; i < node->outputs().size(); ++i) {
604	    GE_ASSERT_SUCCESS(UpdateOutputAttr(node, old_axis_id, to_axis, node->outputs[i].attr),
605	                      "Failed to update repeat and strides for outputs[%u], node = %s(%s)", i, node->GetNamePtr(),
606	                      node->GetTypePtr());
607	  }
608	  GELOGD("Replace axis for node: %s(%s) success", node->GetNamePtr(), node->GetTypePtr());
609	  return af::SUCCESS;
610	}
611	
612	af::Status ConcatFusionCaseGenerator::UpdateOutputAttr(const af::AscNodePtr &node, ascir::AxisId old_axis_id,
613	                                                       const af::Axis &to_axis, af::AscTensorAttr &tensor_attr) {
614	  size_t axis_index = std::numeric_limits<size_t>::max();
615	  for (size_t i = 0UL; i < tensor_attr.axis.size(); ++i) {
616	    if (tensor_attr.axis[i] == old_axis_id) {
617	      tensor_attr.axis[i] = to_axis.id;
618	      axis_index = i;
619	    } else if (tensor_attr.axis[i] == to_axis.id) {
620	      axis_index = i;
621	    }
622	  }
623	  GE_ASSERT_TRUE(axis_index != std::numeric_limits<size_t>::max(),
624	                 "axis id %ld (old) / %ld (new) not found in node %s(%s) tensor_attr.axis", old_axis_id, to_axis.id,
625	                 node->GetNamePtr(), node->GetTypePtr());
626	
627	  auto &repeats = tensor_attr.repeats;
628	  auto &strides = tensor_attr.strides;
629	  GELOGD("before update, repeats = %s, strides = %s", af::ToString(repeats).c_str(), af::ToString(strides).c_str());
630	  GE_ASSERT_TRUE(repeats.size() == strides.size());
631	  GE_ASSERT_TRUE(axis_index < repeats.size(), "axis_index = %zu, out of range [0, %zu)", axis_index, repeats.size());
632	  // concat_dim在brc轴, repeats和strides都不需要update
633	  if (af::SymbolicUtils::StaticCheckEq(repeats[axis_index], af::ops::One) == af::TriBool::kTrue) {
634	    return af::SUCCESS;
635	  }
636	  repeats[axis_index] = to_axis.size;
637	  // Load/Store的stride为GM的stride, 不需要改变
638	  if (af::ops::IsOps<af::ascir_op::Load>(node) || af::ops::IsOps<af::ascir_op::Store>(node)) {
639	    if (af::SymbolicUtils::StaticCheckEq(to_axis.size, af::ops::One) == af::TriBool::kTrue) {
640	      node->outputs[0].attr.strides[axis_index] = af::ops::Zero;
641	    }
642	    return af::SUCCESS;
643	  }
644	  af::Expression stride = af::ops::One;
645	  for (auto i = static_cast<int32_t>(repeats.size() - 1); i >= 0; --i) {
646	    if (i != static_cast<int32_t>(repeats.size() - 1UL)) {
647	      stride = stride * repeats[i + 1];
648	    }
649	    if (af::SymbolicUtils::StaticCheckEq(repeats[i], af::ops::One) == af::TriBool::kTrue) {
650	      strides[i] = af::ops::Zero;
651	    } else {
652	      strides[i] = stride;
653	    }
654	  }
655	  GELOGD("after update, repeats = %s, strides = %s", af::ToString(repeats).c_str(), af::ToString(strides).c_str());
656	  return af::SUCCESS;
657	}
658	
659	Status ConcatFusionCaseGenerator::InsertAxis(const ascir::ImplGraph &optimized_graph) {
660	  const auto graph_attr =
661	      af::AscGraphUtils::GetComputeGraph(optimized_graph)->GetOrCreateAttrsGroup<af::AscGraphAttr>();
662	  GE_ASSERT_NOTNULL(graph_attr);
663	  GELOGD("before: axes = %s", ScheduleUtils::AxesToString(graph_attr->axis).c_str());
664	  const auto src_axes = graph_attr->axis;  // copy
665	  std::vector<af::AxisPtr> new_axes;
666	  for (const auto &src_axis : src_axes) {
667	    std::shared_ptr<af::Axis> new_axis = af::MakeShared<af::Axis>();
668	    GE_CHECK_NOTNULL(new_axis, "create axis failed");
669	    new_axis->id = src_axis->id;
670	    new_axis->name = src_axis->name;
671	    new_axis->type = src_axis->type;
672	    new_axis->size = src_axis->size;
673	    new_axes.push_back(std::move(new_axis));
674	  }
675	
676	  auto new_axis_id = static_cast<int64_t>(new_axes.size());
677	  std::shared_ptr<af::Axis> const_axis = af::MakeShared<af::Axis>();
678	  GE_CHECK_NOTNULL(const_axis, "create axis failed");
679	  const_axis->id = static_cast<int64_t>(new_axes.size());
680	  const_axis->name = "axis_1d";
681	  const_axis->type = af::Axis::kAxisTypeOriginal;
682	  const_axis->size = af::ops::One;
683	  new_axes.push_back(std::move(const_axis));
684	  graph_attr->axis = std::move(new_axes);
685	  GELOGD("after: axes = %s", ScheduleUtils::AxesToString(graph_attr->axis).c_str());
686	
687	  for (const auto &node : optimized_graph.GetAllNodes()) {
688	    if (ScheduleUtils::IsIOBuffer(node)) {
689	      continue;
690	    }
691	    auto cur_axis_ids = node->attr.sched.axis;
692	    node->attr.sched.axis.insert(node->attr.sched.axis.begin(), new_axis_id);
693	    for (const auto output_attr : node->outputs()) {
694	      output_attr->attr.axis.insert(output_attr->attr.axis.begin(), new_axis_id);
695	      if (output_attr->attr.strides[0UL] == 0) {
696	        output_attr->attr.strides.insert(output_attr->attr.strides.begin(), af::ops::One);
697	      } else {
698	        output_attr->attr.strides.insert(output_attr->attr.strides.begin(),
699	                                         af::sym::Mul(output_attr->attr.repeats[0UL], output_attr->attr.strides[0UL]));
700	      }
701	      output_attr->attr.repeats.insert(output_attr->attr.repeats.begin(), af::ops::One);
702	    }
703	  }
704	  return af::SUCCESS;
705	}
706	
707	Status ConcatFusionCaseGenerator::AddTemplateIfCanFitInOneKernel(const af::AscNodePtr &concat_node,
708	                                                                 ascir::HintGraph &graph,
709	                                                                 std::vector<ascir::ImplGraph> &graphs) {
710	  GE_CHK_BOOL_RET_SPECIAL_STATUS(concat_node->inputs.Size() > kMaxInputNum, af::SUCCESS,
711	                                 "input num(%u) > max_input_num(%u), cannot fit in one kernel",
712	                                 concat_node->inputs.Size(), kMaxInputNum);
713	  const auto data_type_size = af::GetSizeByDataType(concat_node->outputs[0].attr.dtype);
714	  GE_ASSERT_TRUE(data_type_size > 0);
715	  const auto max_dim_size = kSmallDimSizeThreshold / data_type_size;
716	  for (uint32_t i = 0U; i < concat_node->inputs.Size(); ++i) {
717	    const auto dim_expr = concat_node->inputs[i].attr.repeats.back();
718	    GE_CHK_BOOL_RET_SPECIAL_STATUS((!dim_expr.IsConstExpr()), af::SUCCESS, "input[%zu] is not known shape: %s", i,
719	                                   af::ToString(concat_node->inputs[i].attr.repeats).c_str());
720	    int64_t dim_size = -1;
721	    GE_ASSERT_TRUE(dim_expr.GetConstValue(dim_size));
722	    GE_CHK_BOOL_RET_SPECIAL_STATUS((dim_size > max_dim_size), af::SUCCESS,
723	                                   "input[%zu] dim_size(%ld) is larger than threshold(%ld)", i, dim_size, max_dim_size);
724	  }
725	  graphs.emplace_back(graph);
726	  return af::SUCCESS;
727	}
728	
729	Status ConcatFusionCaseGenerator::MarkNoMergeFirstAxis(const std::vector<ascir::ImplGraph> &graphs) {
730	  for (const auto &graph : graphs) {
731	    for (const auto &node : graph.GetAllNodes()) {
732	      if (af::ops::IsOps<af::ascir_op::Concat>(node)) {
733	        GE_ASSERT_TRUE(af::AttrUtils::SetBool(node->GetOpDesc(), "_keep_first_axis", true));
734	      }
735	    }
736	  }
737	  return af::SUCCESS;
738	}
739	
740	bool ConcatFusionCaseGenerator::KeepOriginGraph(const af::AscNodePtr &concat_node) const {
741	  bool keep_origin = false;
742	  if (!support_small_tail_) {
743	    constexpr uint32_t kMaxNumInputs = 16;
744	    keep_origin =
745	        has_recompute_ || (concat_node->inputs.Size() <= kMaxNumInputs) || IsSmallBlock(concat_node, concat_dim_);
746	  }
747	  return keep_origin;
748	}
749	
750	bool ConcatFusionCaseGenerator::IsSmallBlock(const af::AscNodePtr &concat_node, size_t concat_dim) {
751	  constexpr int64_t kMaxOutputBlockSize = 16 * 1024;
752	  const auto dtype_size = GetSizeByDataType(concat_node->outputs[0].attr.dtype);
753	  GE_WARN_ASSERT(dtype_size > 0);
754	  const auto &output_repeats = concat_node->outputs[0].attr.repeats;
755	  int64_t output_size = dtype_size;
756	  for (size_t i = concat_dim; i < output_repeats.size(); ++i) {
757	    auto &dim_expr = output_repeats[i];
758	    if (!dim_expr.IsConstExpr()) {
759	      output_size = -1;
760	      break;
761	    }
762	    int64_t dim_size = -1;
763	    GE_WARN_ASSERT(dim_expr.GetConstValue(dim_size));
764	    output_size *= dim_size;
765	  }
766	  const bool is_small_block = ((output_size >= 0) && (output_size < kMaxOutputBlockSize));
767	  GELOGI("output shape = %s, concat_dim = %zu, is_small_block = %d", af::ToString(output_repeats).c_str(), concat_dim,
768	         static_cast<int32_t>(is_small_block));
769	  return is_small_block;
770	}
771	
772	Status ConcatFusionCaseGenerator::ReconnectIfShareSameAncestor(
773	    const std::unordered_map<std::string, af::NodePtr> &name_to_node, const af::InDataAnchorPtr &in_anchor) {
774	  auto src_anchor = in_anchor->GetPeerOutAnchor();
775	  GE_ASSERT_NOTNULL(src_anchor);
776	  auto src_node = src_anchor->GetOwnerNode();
777	  GE_ASSERT_NOTNULL(src_node);
778	  const auto &it = name_to_node.find(src_node->GetName());
779	  if (it != name_to_node.end()) {
780	    in_anchor->UnlinkAll();
781	    GE_ASSERT_GRAPH_SUCCESS(in_anchor->LinkFrom(it->second->GetOutDataAnchor(src_anchor->GetIdx())));
782	  }
783	  return af::SUCCESS;
784	}
785	
786	Status ConcatFusionCaseGenerator::AddExtraShapeEnv(const af::AscNodePtr &concat_node, size_t concat_dim) {
787	  const auto &output_repeats = concat_node->outputs[0].attr.repeats;
788	  // axis开始, concat各输入的轴大小一致
789	  // 符号库无法推导存在限制, 这里将多个轴进行组合进行guard
790	  for (uint32_t k = 1; k < concat_node->inputs.Size(); ++k) {
791	    const auto &input_repeats = concat_node->inputs[k].attr.repeats;
792	    auto input_axis_size = af::ops::One;
793	    auto output_axis_size = af::ops::One;
794	    for (size_t i = output_repeats.size() - 1; i > concat_dim; --i) {
795	      input_axis_size = input_axis_size * input_repeats[i];
796	      output_axis_size = output_axis_size * output_repeats[i];
797	      GE_LOGW_IF(!EXPECT_SYMBOL_EQ(input_axis_size, output_axis_size),
798	                 "expect axis eq failed, concat_dim = %zu, cur_dim = %zu, input_axis_size = %s, output_axis_size = %s",
799	                 concat_dim, i, input_axis_size.Str().get(), output_axis_size.Str().get());
800	    }
801	  }
802	  for (uint32_t k = 1; k < concat_node->inputs.Size(); ++k) {
803	    const auto &input_repeats = concat_node->inputs[k].attr.repeats;
804	    auto input_axis_size = af::ops::One;
805	    af::Expression output_axis_size = af::ops::One;
806	    for (size_t i = concat_dim + 1; i < output_repeats.size(); ++i) {
807	      input_axis_size = input_axis_size * input_repeats[i];
808	      output_axis_size = output_axis_size * output_repeats[i];
809	      GE_LOGW_IF(!EXPECT_SYMBOL_EQ(input_axis_size, output_axis_size),
810	                 "expect axis eq failed, concat_dim = %zu, cur_dim = %zu, input_axis_size = %s, output_axis_size = %s",
811	                 concat_dim, i, input_axis_size.Str().get(), output_axis_size.Str().get());
812	    }
813	  }
814	  return af::SUCCESS;
815	}
816	
817	Status ConcatFusionCaseGenerator::PrepareForModifyingGraph(const af::AscNodePtr &concat_node) {
818	  GE_ASSERT_SUCCESS(CollectBackwardNodes(concat_node, post_concat_nodes_));
819	  GE_ASSERT_SUCCESS(CollectReachableLoadNodes(concat_node, reachable_load_nodes_));
820	  for (const auto &in_anchor_and_node : af::NodeUtils::GetOutDataNodesWithAnchorByIndex(*concat_node, 0)) {
821	    out_node_name_to_indices_[in_anchor_and_node.second->GetName()].emplace_back(in_anchor_and_node.first->GetIdx());
822	  }
823	  return af::SUCCESS;
824	}
825	
826	Status ConcatFusionCaseGenerator::RunCastOptimizationPass(std::vector<ascir::ImplGraph> &graphs) {
827	  const auto backend_spec = BackendSpec::GetInstance();
828	  GE_ASSERT_NOTNULL(backend_spec);
829	  for (auto &graph : graphs) {
830	    GE_ASSERT_SUCCESS(af::optimize::CastOptimizationPass::Run(graph, backend_spec->concat_alg));
831	  }
832	  return af::SUCCESS;
833	}
834	}  // namespace optimize
